import {
  formatCalendarDate,
  type CalendarDateValue,
} from "../core/calendar-date";

import type { CandidateEmptyCopy } from "./candidate-empty-copy";

export interface CareerHistoryItem {
  title: ReactNode;
  company?: ReactNode;
  /** Host-formatted date text takes precedence over raw dates. */
  dateRange?: ReactNode;
  startDate?: CalendarDateValue;
  endDate?: CalendarDateValue;
  current?: boolean;
  description?: ReactNode;
  /** Stable host grouping key when `company` is not a string. */
  companyGroup?: string;
}

export interface CareerDateRangeProps {
  start?: CalendarDateValue;
  end?: CalendarDateValue;
  current?: boolean;
  presentLabel?: ReactNode;
  locale?: string;
}

/** Absolute calendar dates for a career history; never relative to today. */
export function CareerDateRange({
  start,
  end,
  current = false,
  presentLabel = "Present",
  locale = "en",
}: CareerDateRangeProps) {
  const startLabel = formatCalendarDate(start, locale);
  const endLabel = current ? presentLabel : formatCalendarDate(end, locale);
  if (!startLabel && !endLabel) return null;

  return (
    <>
      {startLabel}
      {startLabel && endLabel ? <span aria-hidden> – </span> : null}
      {endLabel}
    </>
  );
}

interface CareerCompanyGroup {
  key: string | null;
  items: CareerHistoryItem[];
}

function companyGroupKey(item: CareerHistoryItem): string | null {
  if (item.companyGroup?.trim()) return item.companyGroup.trim().toLocaleLowerCase();
  return typeof item.company === "string"
    ? item.company.trim().toLocaleLowerCase() || null
    : null;
}

function groupConsecutiveEmployments(
  items: readonly CareerHistoryItem[],
): CareerCompanyGroup[] {
  return items.reduce<CareerCompanyGroup[]>((groups, item) => {
    const key = companyGroupKey(item);
    const previous = groups.at(-1);

    if (key && previous?.key === key) {
      previous.items.push(item);
    } else {
      groups.push({ key, items: [item] });
    }
    return groups;
  }, []);
}

function descriptionParts(description: string): string[] {
  const parts = description
    .split(/\r?\n|\s+[•●]\s+/)
    .map((part) => part.replace(/^[-–—•●]\s*/, "").trim())
    .filter(Boolean);
  return parts.length > 0 ? parts : [description.trim()];
}

function CareerDescription({ description }: { description: ReactNode }) {
  const [expanded, setExpanded] = useState(false);

  if (typeof description !== "string") {
    return (
      <Text as="div" variant="caption" size="xs" tone="subtle">
        {description}
      </Text>
    );
  }

  const trimmed = description.trim();
  if (!trimmed) return null;
  const parts = descriptionParts(trimmed);
  const hasMore = parts.length > 3 || (parts.length === 1 && trimmed.length > 180);
  const visibleParts = expanded ? parts : parts.slice(0, 3);

  return (
    <Stack gap="xs">
      {parts.length > 1 ? (
        <List
          marker="disc"
          spacing="tight"
          textSize="xs"
          tone="muted"
          className="leading-relaxed"
        >
          {visibleParts.map((part, index) => (
            <ListItem key={index}>{part}</ListItem>
          ))}
        </List>
      ) : (
        <Text
          variant="caption"
          size="xs"
          tone="subtle"
          lineClamp={!expanded && hasMore ? 3 : undefined}
        >
          {trimmed}
        </Text>
      )}
      {hasMore ? (
        <Button
          type="button"
          variant="link-muted"
          size="bare"
          aria-expanded={expanded}
          onClick={() => setExpanded((value) => !value)}
        >
          {expanded ? "Show less" : "Show more"}
        </Button>
      ) : null}
    </Stack>
  );
}

function CareerRole({
  item,
  detailed,
  locale,
  presentLabel,
}: {
  item: CareerHistoryItem;
  detailed: boolean;
  locale: string;
  presentLabel: ReactNode;
}) {
  const date = item.dateRange ?? (
    <CareerDateRange
      start={item.startDate}
      end={item.endDate}
      current={item.current}
      locale={locale}
      presentLabel={presentLabel}
    />
  );
  const hasDate = item.dateRange != null || item.startDate != null || item.endDate != null || item.current;

  return (
    <Stack gap="xs" minWidth="zero">
      <Heading level={5}>{item.title}</Heading>
      {item.company != null || hasDate ? (
        <Text variant="caption" size="xs">
          {item.company}
          {item.company != null && hasDate ? <span aria-hidden> · </span> : null}
          {hasDate ? date : null}
        </Text>
      ) : null}
      {detailed && item.description != null ? (
        <CareerDescription description={item.description} />
      ) : null}
    </Stack>
  );
}

export interface CandidateCareerHistoryTimelineProps {
  items: readonly CareerHistoryItem[];
  loading?: boolean;
  /** The blank slate's wording. Defaults to "No career history yet". */
  empty?: CandidateEmptyCopy;
  /** @deprecated Use `empty.title`. */
  emptyTitle?: string;
  /** @deprecated Use `empty.description`. */
  emptyDescription?: string;
  earlierLabel?: ReactNode;
  presentLabel?: ReactNode;
  detailedCompanyGroups?: number;
  locale?: string;
  className?: string;
}

export function CandidateCareerHistoryTimeline({
  items,
  loading = false,
  empty,
  emptyTitle,
  emptyDescription,
  earlierLabel = "Earlier",
  presentLabel = "Present",
  detailedCompanyGroups = 2,
  locale = "en",
  className,
}: CandidateCareerHistoryTimelineProps) {
  if (loading && items.length === 0) {
    return (
      <Stack data-slot="candidate-career-history-loading" gap="compact" className={className}>
        <Skeleton preset="row-compact" />
        <Skeleton preset="row-compact" />
      </Stack>
    );
  }

  if (items.length === 0) {
    return (
      <EmptyState
        variant="empty"
        size="inline"
        title={empty?.title ?? emptyTitle ?? "No career history yet"}
        description={empty ? empty.description : emptyDescription ?? "Career history is not available."}
        className={className}
      />
    );
  }

  const groups = groupConsecutiveEmployments(items);
  const detailedItems = groups
    .slice(0, detailedCompanyGroups)
    .flatMap((group) => group.items);
  const earlierItems = groups
    .slice(detailedCompanyGroups)
    .flatMap((group) => group.items);

  return (
    <Stack data-slot="candidate-career-history" gap="lg" className={className}>
      <Stack gap="lg">
        {detailedItems.map((item, index) => (
          <CareerRole
            key={index}
            item={item}
            detailed
            locale={locale}
            presentLabel={presentLabel}
          />
        ))}
      </Stack>
      {earlierItems.length > 0 ? (
        <Stack gap="md">
          <Separator />
          <SectionHeader label={earlierLabel} spacing="none" />
          <List spacing="normal">
            {earlierItems.map((item, index) => (
              <ListItem key={index}>
                <CareerRole
                  item={item}
                  detailed={false}
                  locale={locale}
                  presentLabel={presentLabel}
                />
              </ListItem>
            ))}
          </List>
        </Stack>
      ) : null}
    </Stack>
  );
}

"use client";

import { Anchor } from "@epicbagel/saas-kit/primitives/anchor";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import type { ElementType, HTMLAttributes, MouseEvent } from "react";

import { COARSE_POINTER_TOUCH_TARGET } from "./touch-targets";

/** One way to reach a person, with the link the host built for it. */
export interface CandidateChannel {
  /** What the channel is, such as `email`, `phone` or `profile`. Marks the action `data-channel`; two channels may share one. */
  kind: string;
  /** Where the action goes: a `mailto:` or `tel:` link, or a web address. */
  href: string;
  /** The visible label in a bar; the tooltip and accessible name of an icon, such as "Email Mei Example". */
  label: string;
  /** The glyph, as a component reference such as a lucide icon. */
  icon: ElementType;
  /** Opens in a new tab. Defaults to true for an `http(s)` link and false otherwise. */
  external?: boolean;
}

export interface CandidateChannelActionsProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /** The channels, in order. Leave out any the host has no address for. */
  channels: readonly CandidateChannel[];
  /**
   * `icons`: a row of round icon links. `bar`: labelled links that share a
   * row equally, for an action bar; a link too narrow for its label (five
   * channels on a phone) shows the glyph alone, still named by the label.
   */
  presentation?: "icons" | "bar";
  /**
   * Icon size: `default` keeps the kit's 44px touch target, `compact` suits a
   * dense card row. On a coarse pointer (a touchscreen) every link is at
   * least 44px square at either size, so a phone keeps the touch target.
   */
  size?: "default" | "compact";
  /** The group's accessible name, such as "Contact Mei Example". */
  label?: string;
}

const isWebLink = (href: string) => /^https?:\/\//i.test(href);

// Shown from 4.5rem of room inside the link: the glyph, its gap and about six
// characters. Below that the link is the glyph alone.
const BAR_LABEL_VISIBILITY = "hidden @min-[4.5rem]:inline";

/**
 * The ways to reach a person (email, call, message, an external profile) as
 * plain links: round icon buttons, or a labelled bar whose links share the
 * row in equal parts. A bar link narrower than a short label (a container
 * query on the link) drops to its glyph, so a phone shows a row of icons
 * rather than one letter and an ellipsis each. The host builds each link,
 * so the package knows no address scheme or network; a web link opens in a
 * new tab.
 *
 * Every link is at least 44px square on a coarse pointer (a touchscreen): a
 * bar link at any width, an icon at either size, even where the kit scales
 * its rem sizes down on a narrow screen.
 *
 * Clicks never reach a surrounding clickable card. The root is marked
 * `data-slot="candidate-channel-actions"` and is a labelled group; each link
 * is the kit Button, keeping its own `data-slot="button"`, with
 * `data-channel` set to the channel's `kind`. With no channels it renders
 * nothing.
 */
export function CandidateChannelActions({
  channels,
  presentation = "icons",
  size = "default",
  label = "Contact",
  ...props
}: CandidateChannelActionsProps) {
  if (channels.length === 0) return null;
  const bar = presentation === "bar";

  return (
    <Stack
      data-slot="candidate-channel-actions"
      data-presentation={presentation}
      role="group"
      aria-label={label}
      direction="horizontal"
      gap={bar ? "sm" : "xs"}
      align="center"
      justify={bar ? "center" : "start"}
      width={bar ? "full" : "auto"}
      {...props}
    >
      {channels.map((channel, index) => {
        // Two channels can share a kind (two phone numbers), so the position keys them.
        const key = `${index}:${channel.kind}`;
        const external = channel.external ?? isWebLink(channel.href);
        const link = (
          <Anchor
            href={channel.href}
            data-channel={channel.kind}
            title={channel.label}
            // The name in both forms: a bar link can hide its text when narrow.
            aria-label={channel.label}
            {...(external ? { target: "_blank", rel: "noopener noreferrer" } : {})}
            onClick={(event: MouseEvent<HTMLAnchorElement>) => event.stopPropagation()}
          >
            <Icon icon={channel.icon} size="md" />
            {bar ? (
              <Text
                variant="inherit"
                as="span"
                truncate
                minWidth="zero"
                className={BAR_LABEL_VISIBILITY}
              >
                {channel.label}
              </Text>
            ) : null}
          </Anchor>
        );
        return bar ? (
          // A size container, so its label can query the link's own width;
          // that also makes the links share the row equally.
          <Button
            key={key}
            asChild
            variant="outline"
            size="sm"
            grow
            minWidth="zero"
            className={`@container ${COARSE_POINTER_TOUCH_TARGET}`}
          >
            {link}
          </Button>
        ) : (
          <Button
            key={key}
            asChild
            variant="outline"
            shape="circle"
            size={size === "compact" ? "icon-compact" : "icon-sm"}
            shrink
            className={COARSE_POINTER_TOUCH_TARGET}
          >
            {link}
          </Button>
        );
      })}
    </Stack>
  );
}

"use client";

import { Button } from "@epicbagel/saas-kit/primitives/button";
import { CountBadge } from "@epicbagel/saas-kit/primitives/count-badge";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@epicbagel/saas-kit/primitives/dropdown-menu";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Check, ChevronDown } from "lucide-react";
import type { ReactNode } from "react";

/** One way of reaching a candidate, such as email or phone. */
export interface CandidateContactChannelOption {
  id: string;
  label: ReactNode;
}

/** Host-owned wording for the trigger and the remove items. */
export interface CandidateContactChannelsMenuLabels {
  trigger: ReactNode;
  /** The trigger's text when `compact`. */
  compactTrigger: ReactNode;
  /** Tooltip on the trigger. */
  triggerTitle: string;
  /** The item that clears a channel recorded by mistake. */
  remove: (option: CandidateContactChannelOption) => ReactNode;
}

const DEFAULT_LABELS: CandidateContactChannelsMenuLabels = {
  trigger: "Contacted via",
  compactTrigger: "Via",
  triggerTitle: "Record how this candidate was contacted",
  remove: (option) => <>Remove {option.label}</>,
};

export interface CandidateContactChannelsMenuProps {
  /** The channels, in menu order. */
  options: readonly CandidateContactChannelOption[];
  /**
   * The channels already used, by option id, each with what to show beside it
   * (usually how recently). An id that is absent, null, undefined or false
   * has not been used.
   */
  touched: Readonly<Record<string, ReactNode>>;
  /** Called when a channel is picked; picking a used channel again refreshes it. */
  onTouch: (id: string) => void;
  /** Called from the remove items. */
  onRemove: (id: string) => void;
  /** A shorter trigger for tight action rows. */
  compact?: boolean;
  labels?: Partial<CandidateContactChannelsMenuLabels>;
}

function isTouched(value: ReactNode): boolean {
  return value != null && value !== false;
}

/**
 * Records how a candidate was contacted. Each pick records or refreshes a
 * channel and the menu stays open, so ticking two is one visit; used channels
 * show the host's recency text and can be removed.
 *
 * Every click stops propagating, because the menu often sits inside a
 * clickable candidate card and React events bubble through portals along the
 * component tree. The host owns the channels, timestamps, recency wording and
 * anything a first contact should change.
 */
export function CandidateContactChannelsMenu({
  options,
  touched,
  onTouch,
  onRemove,
  compact = false,
  labels,
}: CandidateContactChannelsMenuProps) {
  const text = { ...DEFAULT_LABELS, ...labels };
  const used = options.filter((option) => isTouched(touched[option.id]));

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          size="sm"
          variant="outline"
          title={text.triggerTitle}
          onClick={(event) => event.stopPropagation()}
        >
          {compact ? text.compactTrigger : text.trigger}
          {used.length > 0 && <CountBadge value={used.length} variant="secondary" />}
          <Icon icon={ChevronDown} size="md" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="start"
        data-slot="candidate-contact-channels-menu"
        onClick={(event) => event.stopPropagation()}
      >
        {options.map((option) => {
          const recency = touched[option.id];
          const isUsed = isTouched(recency);
          return (
            <DropdownMenuItem
              key={option.id}
              // Stay open so ticking two channels is one menu visit.
              onSelect={(event) => event.preventDefault()}
              onClick={(event) => {
                event.stopPropagation();
                onTouch(option.id);
              }}
            >
              <Icon icon={Check} size="md" tone="success" visibility={isUsed ? "visible" : "hidden"} />
              {option.label}
              {isUsed && recency !== true && (
                <Text variant="inherit" as="span" grow align="end" paddingX="md" size="xs" tone="muted">
                  {recency}
                </Text>
              )}
            </DropdownMenuItem>
          );
        })}
        {used.length > 0 && (
          <>
            <DropdownMenuSeparator />
            {used.map((option) => (
              <DropdownMenuItem
                key={`rm-${option.id}`}
                tone="muted"
                onClick={(event) => {
                  event.stopPropagation();
                  onRemove(option.id);
                }}
              >
                {text.remove(option)}
              </DropdownMenuItem>
            ))}
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { Anchor } from "@epicbagel/saas-kit/primitives/anchor";
import { DefinitionItem, DefinitionList } from "@epicbagel/saas-kit/primitives/definition-list";
import { EmptyState } from "@epicbagel/saas-kit/primitives/empty-state";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { SectionHeader } from "@epicbagel/saas-kit/primitives/section-header";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { BadgeCheck, ExternalLink, Link2, Mail, MapPin, Phone, Send } from "lucide-react";
import type { HTMLAttributes, Key, ReactNode } from "react";

import type { CandidateEmptyCopy } from "./candidate-empty-copy";

function present(value: ReactNode): boolean {
  return value != null && value !== false && value !== "";
}

export interface CandidateContactDetailsLabels {
  title: ReactNode;
  email: ReactNode;
  /** The verified mark's accessible name. */
  emailVerified: string;
  phone: ReactNode;
  /** The external profile row's label, such as the network's name. */
  profile: ReactNode;
  /** The external profile link's text. */
  profileLink: ReactNode;
  location: ReactNode;
}

const CONTACT_LABELS: CandidateContactDetailsLabels = {
  title: "Contact",
  email: "Email",
  emailVerified: "Email verified",
  phone: "Phone",
  profile: "Profile",
  profileLink: "Profile",
  location: "Location",
};

export interface CandidateContactDetailsProps
  extends Omit<HTMLAttributes<HTMLElement>, "title" | "children"> {
  /** Linked with `mailto:`. */
  email?: string | null;
  /** Adds a success-toned check after the address. */
  emailVerified?: boolean;
  /** The number, already formatted or as a phone-number component. */
  phone?: ReactNode;
  /** An external profile, opened in a new tab. */
  profileUrl?: string | null;
  location?: ReactNode;
  labels?: Partial<CandidateContactDetailsLabels>;
  /** The kit PanelSection's divider. */
  border?: "none" | "top" | "bottom";
}

/**
 * How to reach a person, as a divided definition list: email (with a
 * verified mark), phone, an external profile and location. A row shows only
 * when its value is given.
 *
 * The root is the kit PanelSection, marked `data-slot="candidate-contact-details"`.
 */
export function CandidateContactDetails({
  email,
  emailVerified = false,
  phone,
  profileUrl,
  location,
  labels,
  border = "bottom",
  ...props
}: CandidateContactDetailsProps) {
  const wording = { ...CONTACT_LABELS, ...labels };

  return (
    <PanelSection data-slot="candidate-contact-details" border={border} {...props}>
      <SectionHeader label={wording.title} />
      <DefinitionList variant="divided">
        {email && (
          <DefinitionItem label={wording.email}>
            <Text variant="inherit" as="span" display="inline-flex">
              <Anchor href={`mailto:${email}`} variant="text" display="inline-flex">
                <Icon icon={Mail} size="xs" />
                {email}
              </Anchor>
              {emailVerified && (
                <Icon icon={BadgeCheck} size="sm" tone="success" aria-label={wording.emailVerified} />
              )}
            </Text>
          </DefinitionItem>
        )}
        {present(phone) && (
          <DefinitionItem label={wording.phone}>
            <Text variant="inherit" as="span" display="inline-flex">
              <Icon icon={Phone} size="xs" tone="muted" />
              {phone}
            </Text>
          </DefinitionItem>
        )}
        {profileUrl && (
          <DefinitionItem label={wording.profile}>
            <Anchor
              href={profileUrl}
              target="_blank"
              rel="noopener noreferrer"
              variant="text"
              display="inline-flex"
            >
              <Icon icon={Link2} size="xs" />
              {wording.profileLink}
              <Icon icon={ExternalLink} size="xs" />
            </Anchor>
          </DefinitionItem>
        )}
        {present(location) && (
          <DefinitionItem label={wording.location}>
            <Text variant="inherit" as="span" display="inline-flex">
              <Icon icon={MapPin} size="xs" tone="muted" />
              {location}
            </Text>
          </DefinitionItem>
        )}
      </DefinitionList>
    </PanelSection>
  );
}

/** One channel a person was contacted on. */
export interface CandidateChannelLogEntry {
  id?: Key;
  /** The channel's name. */
  label: ReactNode;
  /** When it was last used, already formatted. */
  when: ReactNode;
}

export interface CandidateChannelLogProps
  extends Omit<HTMLAttributes<HTMLElement>, "title" | "children"> {
  /** The section heading, such as which role the outreach is for. */
  title: ReactNode;
  /** The channels used, in the order to show them, usually most recent first. */
  entries: readonly CandidateChannelLogEntry[];
  /** The blank slate's wording. Defaults to "No outreach logged yet". */
  empty?: CandidateEmptyCopy;
  /** Under the log, the control that records a channel, such as a CandidateContactChannelsMenu. */
  control?: ReactNode;
  /** The kit PanelSection's divider. */
  border?: "none" | "top" | "bottom";
}

/**
 * Which channels a person has been contacted on, and when, as a divided
 * definition list, or the kit's empty state when none is recorded, with the
 * host's recording control underneath.
 *
 * The root is the kit PanelSection, marked `data-slot="candidate-channel-log"`.
 */
export function CandidateChannelLog({
  title,
  entries,
  empty = { title: "No outreach logged yet" },
  control,
  border = "bottom",
  ...props
}: CandidateChannelLogProps) {
  return (
    <PanelSection data-slot="candidate-channel-log" border={border} {...props}>
      <SectionHeader label={title} />
      {entries.length > 0 ? (
        <DefinitionList variant="divided">
          {entries.map((entry, index) => (
            <DefinitionItem key={entry.id ?? index} label={entry.label}>
              {entry.when}
            </DefinitionItem>
          ))}
        </DefinitionList>
      ) : (
        <EmptyState
          variant="empty"
          size="inline"
          icon={Send}
          title={empty.title}
          description={empty.description}
        />
      )}
      {present(control) && (
        <Text as="div" variant="inherit" marginTop="md">
          {control}
        </Text>
      )}
    </PanelSection>
  );
}

/** One labelled value in a CandidateDefinitionSection. */
export interface CandidateDefinitionItem {
  id?: Key;
  label: ReactNode;
  /** An empty value leaves the row out. */
  value: ReactNode;
}

export interface CandidateDefinitionSectionProps
  extends Omit<HTMLAttributes<HTMLElement>, "title" | "children"> {
  /** The section heading. */
  title: ReactNode;
  items: readonly CandidateDefinitionItem[];
  /** The kit PanelSection's divider. */
  border?: "none" | "top" | "bottom";
}

/**
 * A titled, divided list of labelled values about a person, such as their
 * experience, salary and documents. Rows without a value are left out, and
 * with none left it renders nothing.
 *
 * The root is the kit PanelSection, marked `data-slot="candidate-definition-section"`.
 */
export function CandidateDefinitionSection({
  title,
  items,
  border = "bottom",
  ...props
}: CandidateDefinitionSectionProps) {
  const shown = items.filter((item) => present(item.value));
  if (shown.length === 0) return null;

  return (
    <PanelSection data-slot="candidate-definition-section" border={border} {...props}>
      <SectionHeader label={title} />
      <DefinitionList variant="divided">
        {shown.map((item, index) => (
          <DefinitionItem key={item.id ?? index} label={item.label}>
            {item.value}
          </DefinitionItem>
        ))}
      </DefinitionList>
    </PanelSection>
  );
}

import { cn } from "@epicbagel/saas-kit/lib/utils";
import { AspectRatio } from "@epicbagel/saas-kit/primitives/aspect-ratio";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import type { HTMLAttributes, ReactNode } from "react";

export interface CandidateCoverImageProps
  extends HTMLAttributes<HTMLDivElement> {
  /** Caller-owned media. The host owns source resolution and alt text. */
  children?: ReactNode;
  /** `compact` keeps the 4:1 ratio until the frame reaches 96px high. */
  size?: CandidateCoverImageSize;
  softenUntilHover?: boolean;
}

/** The shared cover's height: its full ratio, or capped for a condensed card. */
export type CandidateCoverImageSize = "default" | "compact";

/** A stable 4:1 media frame that performs no fetching or URL resolution. */
export function CandidateCoverImage({
  children,
  size = "default",
  softenUntilHover = false,
  className,
  ...props
}: CandidateCoverImageProps) {
  if (children == null) return null;

  const frameProps = {
    "data-slot": "candidate-cover-image",
    className: cn(
      "w-full overflow-hidden bg-muted [&_img]:h-full [&_img]:w-full [&_img]:object-cover [&_img]:object-center",
      size === "compact" && "relative aspect-[4/1] max-h-[96px]",
      softenUntilHover &&
        "[&_img]:opacity-75 [&_img]:grayscale-[0.2] group-hover:[&_img]:opacity-100 group-hover:[&_img]:grayscale-0",
      className,
    ),
    ...props,
  };
  // Radix reserves its height on an outer padding wrapper. Native aspect-ratio
  // lets max-height cap the actual layout space, rather than just its image.
  return size === "compact" ? (
    <div {...frameProps}>{children}</div>
  ) : (
    <AspectRatio ratio={4} {...frameProps}>{children}</AspectRatio>
  );
}

export interface CandidateCoverHeaderProps
  extends HTMLAttributes<HTMLDivElement> {
  cover?: ReactNode;
  /** The cover's size; the default keeps its full 4:1 ratio. */
  coverSize?: CandidateCoverImageSize;
  children: ReactNode;
  /**
   * Space around the identity. `none` sits it flush in a container the host
   * pads; with no cover the header then doesn't clip, so a focus ring at its
   * edge stays whole. `dialog` pads it like the kit's dialog header (16px), so
   * as a CandidateProfileDialog's `header` it starts at the body's left edge.
   */
  padding?: CandidateCoverHeaderPadding;
  softenCoverUntilHover?: boolean;
}

/** The space a CandidateCoverHeader leaves around the identity. */
export type CandidateCoverHeaderPadding = "compact" | "card-header" | "lg" | "dialog" | "none";

/**
 * `dialog`: the kit's ResponsiveDialogHeader padding. Its inline padding is
 * the ResponsiveDialogBody's (px-4), which is what lines the two up.
 */
const DIALOG_PADDING = "p-4";

/** One cover-and-identity hierarchy shared by candidate cards and profiles. */
export function CandidateCoverHeader({
  cover,
  coverSize = "default",
  children,
  padding = "card-header",
  softenCoverUntilHover = false,
  className,
  ...props
}: CandidateCoverHeaderProps) {
  // The clip keeps a cover inside the rounded frame; a flush header with no
  // cover has nothing to clip, and clipping would cut its focus rings.
  const clip = cover != null || padding !== "none";

  return (
    <div
      data-slot="candidate-cover-header"
      className={cn(clip && "overflow-hidden", className)}
      {...props}
    >
      <CandidateCoverImage size={coverSize} softenUntilHover={softenCoverUntilHover}>
        {cover}
      </CandidateCoverImage>
      <PanelSection
        as="div"
        padding={padding === "none" || padding === "dialog" ? "none" : padding === "compact" ? "compact" : "default"}
        className={cn(padding === "card-header" && "pb-3 pt-5", padding === "dialog" && DIALOG_PADDING)}
      >
        {children}
      </PanelSection>
    </div>
  );
}

