/** Host-owned wording for the two states of the toggle. */
export interface CandidateFavouriteButtonLabels {
  /** Shown while the candidate is not a favourite. */
  add: string;
  /** Shown while the candidate is a favourite. */
  remove: string;
}

const DEFAULT_LABELS: CandidateFavouriteButtonLabels = {
  add: "Add to favourites",
  remove: "Remove from favourites",
};

export interface CandidateFavouriteButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children" | "type" | "onToggle"> {
  favourited: boolean;
  /** Called with no arguments; the host flips and persists the marker. */
  onToggle: () => void;
  labels?: Partial<CandidateFavouriteButtonLabels>;
  /**
   * The star's colour while the candidate is not a favourite: `muted`
   * (default) on a card, or `inherit` to take the surrounding text colour,
   * as the other icon actions in a detail header do.
   */
  idleTone?: "muted" | "inherit";
}

/**
 * A borderless star toggle for marking a candidate as a favourite.
 *
 * The click never reaches a surrounding card, so it works inside a clickable
 * candidate card. The root is the kit Button and keeps the kit's own
 * `data-slot="button"`, which theme stylesheets select on.
 */
export function CandidateFavouriteButton({
  favourited,
  onToggle,
  labels,
  idleTone = "muted",
  onClick,
  ...props
}: CandidateFavouriteButtonProps) {
  const label = favourited
    ? labels?.remove ?? DEFAULT_LABELS.remove
    : labels?.add ?? DEFAULT_LABELS.add;

  return (
    <Button
      type="button"
      variant="ghost"
      size="icon-sm"
      shrink
      aria-pressed={favourited}
      title={label}
      {...props}
      onClick={(event: MouseEvent<HTMLButtonElement>) => {
        event.stopPropagation();
        onClick?.(event);
        if (!event.defaultPrevented) onToggle();
      }}
    >
      <Icon icon={Star} size="md" tone={favourited ? "warning" : idleTone} filled={favourited} />
    </Button>
  );
}

"use client";

import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Toggle } from "@epicbagel/saas-kit/primitives/toggle";
import type { ElementType, HTMLAttributes, ReactNode } from "react";

import { COARSE_POINTER_TOUCH_TARGET } from "./touch-targets";

/**
 * The kit Toggle's pressed state is a light accent fill with the same label
 * colour as an unpressed chip, about 1.2:1 against it. These are the kit
 * ChipTabs' outline states instead: an unpressed chip has a muted label, and
 * the pressed one a primary border and tint with a full-strength label.
 */
const CHIP_STATES =
  "text-muted-foreground hover:text-foreground data-[state=on]:border-primary data-[state=on]:bg-primary/10 data-[state=on]:font-medium data-[state=on]:text-foreground";

const CHIP_CLASSES = `${CHIP_STATES} ${COARSE_POINTER_TOUCH_TARGET}`;

/** One chip: a value the list can be narrowed to. */
export interface CandidateFilterChipOption<TValue extends string = string> {
  value: TValue;
  label: ReactNode;
  /** An icon component (not an element) drawn before the label. */
  icon?: ElementType;
}

export interface CandidateFilterChipsProps<TValue extends string = string>
  extends Omit<HTMLAttributes<HTMLElement>, "onChange" | "children"> {
  /** The chosen option, or null for the unfiltered chip. */
  value: TValue | null;
  /** Called with an option's value, or null from the unfiltered chip. */
  onChange: (value: TValue | null) => void;
  /** The first chip, which clears the filter, such as "Everyone". */
  allLabel: ReactNode;
  options: readonly CandidateFilterChipOption<TValue>[];
  /** Content before the chips, such as a badge naming where the list came from. */
  context?: ReactNode;
  /** Content pushed to the end of the row, such as a related control. */
  action?: ReactNode;
}

/**
 * A single row of pressed-state chips that narrows a list of people to one
 * kind, such as everyone with a recent job move. The row scrolls sideways
 * rather than wrapping, and sits on a bottom border so it reads as part of
 * the toolbar above the list. Each chip is a toggle button with
 * `aria-pressed`; the pressed one has a primary border and tint and a
 * full-strength label, the others a muted label. Every chip keeps a 44px
 * touch target on a coarse pointer (a touchscreen); a mouse keeps the 28px
 * chip. The host owns the options, their
 * wording and what each one filters. The root is marked
 * `data-slot="candidate-filter-chips"`.
 */
export function CandidateFilterChips<TValue extends string = string>({
  value,
  onChange,
  allLabel,
  options,
  context,
  action,
  ...props
}: CandidateFilterChipsProps<TValue>) {
  return (
    <Stack gap="none" border="bottom" data-slot="candidate-filter-chips" {...props}>
      <Stack direction="horizontal" gap="xs" align="center" paddingY="sm" overflow="x-auto">
        {context}
        <Toggle
          pressed={!value}
          onPressedChange={() => onChange(null)}
          variant="outline"
          size="chip"
          className={CHIP_CLASSES}
        >
          {allLabel}
        </Toggle>
        {options.map((option) => (
          <Toggle
            key={option.value}
            pressed={value === option.value}
            onPressedChange={() => onChange(option.value)}
            variant="outline"
            size="chip"
            className={CHIP_CLASSES}
          >
            {option.icon && <Icon icon={option.icon} size="xs" />}
            {option.label}
          </Toggle>
        ))}
        {action && <Stack marginStart="auto" shrink={false}>{action}</Stack>}
      </Stack>
    </Stack>
  );
}

import { Badge, type BadgeProps } from "@epicbagel/saas-kit/primitives/badge";
import { SentimentBadge, type Sentiment } from "@epicbagel/saas-kit/primitives/sentiment-dot";
import type { HTMLAttributes, ReactNode } from "react";

export type CandidateGrade = "A" | "B" | "C" | "D";

/** Host-owned wording for each display grade. */
export type CandidateGradeLabels = Partial<Record<CandidateGrade, string>>;

/** Visual treatment selected by the host; Recruit UI does not infer grade policy. */
export type CandidateGradeTone =
  | "default"
  | "secondary"
  | "destructive"
  | "outline"
  | "success"
  | "warning"
  | "error"
  | "info"
  | "neutral";

export function normalizeCandidateGrade(
  grade: string | null | undefined,
): CandidateGrade | null {
  const normalized = grade?.trim().toUpperCase();
  return normalized === "A" ||
    normalized === "B" ||
    normalized === "C" ||
    normalized === "D"
    ? normalized
    : null;
}

/** Return presentation only; grade assignment and vocabulary stay host-owned. */
export function candidateGradeLetter(grade: string | null | undefined): string {
  return normalizeCandidateGrade(grade) ?? "—";
}

export function candidateGradeLabel(
  grade: string | null | undefined,
  labels: CandidateGradeLabels,
): string | null {
  const normalized = normalizeCandidateGrade(grade);
  return normalized ? labels[normalized] ?? null : null;
}

export function candidateGradeDisplay(
  grade: string | null | undefined,
  labels: CandidateGradeLabels,
): string {
  const normalized = normalizeCandidateGrade(grade);
  if (!normalized) return "—";
  const label = labels[normalized];
  return label ? `${normalized} — ${label}` : normalized;
}

export interface CandidateGradeBadgeProps
  extends HTMLAttributes<HTMLDivElement> {
  grade: string | null | undefined;
  /**
   * One-off host wording. Takes precedence over `labels`. With no grade, the
   * inline format shows it alone, such as "Needs review", in place of the
   * dash.
   */
  label?: ReactNode;
  /** Host-owned wording map for shared badge instances. */
  labels?: CandidateGradeLabels;
  /** Host-owned semantic treatment; no meaning is inferred from the letter. */
  tone?: CandidateGradeTone;
  showLabel?: boolean;
  /** The kit badge size, such as `compact` for dense rows. */
  size?: BadgeProps["size"];
  /** Root element: a block-level `div` (default) or an inline `span`. */
  as?: "div" | "span";
  /** Keep the badge at its natural width in a flex row. */
  shrink?: boolean;
  /**
   * `split` (default): the letter and the label as separate spans, the letter
   * with an accessible name. `inline`: a single line of text, "A — Strong fit",
   * for a host that names the grade in a tooltip or the surrounding text; with
   * no grade, the label alone, or "—" without one.
   */
  format?: "split" | "inline";
  /**
   * `badge` (default): the kit Badge in `tone`. `sentiment`: the kit's
   * sentiment pill, a coloured dot and text, in `sentiment`. The pill takes
   * only `className`; other attributes are not passed to it.
   */
  appearance?: "badge" | "sentiment";
  /** Host-owned sentiment for `appearance="sentiment"`. */
  sentiment?: CandidateGradeSentiment;
}

/** The kit's sentiment scale, for `appearance="sentiment"`. */
export type CandidateGradeSentiment = Sentiment;

function inlineGradeText(
  grade: CandidateGrade | null,
  label: ReactNode,
): ReactNode {
  const hasLabel = !(label == null || label === false || label === "");
  // An ungraded record with host wording reads as that wording alone.
  if (!grade) return hasLabel ? label : "—";
  if (!hasLabel) return grade;
  // One text node when the label is plain text, as candidateGradeDisplay
  // would format it.
  return typeof label === "string" || typeof label === "number"
    ? `${grade} — ${label}`
    : <>{grade} — {label}</>;
}

/**
 * The grade letter with an optional host label. The root is the kit Badge
 * (or its sentiment pill) and keeps the kit's own `data-slot`, which theme
 * stylesheets select on; `data-grade` names the grade, or `ungraded`.
 */
export function CandidateGradeBadge({
  grade,
  label,
  labels = {},
  tone = "neutral",
  showLabel = true,
  size,
  as,
  shrink,
  format = "split",
  appearance = "badge",
  sentiment = "neutral",
  className,
  ...props
}: CandidateGradeBadgeProps) {
  const normalized = normalizeCandidateGrade(grade);
  const resolvedLabel = label === undefined
    ? candidateGradeLabel(normalized, labels)
    : label;
  const visibleLabel = showLabel ? resolvedLabel : null;

  const content = format === "inline"
    ? inlineGradeText(normalized, visibleLabel)
    : (
      <>
        <span aria-label={normalized ? `Grade ${normalized}` : "Not graded"}>
          {normalized ?? "—"}
        </span>
        {visibleLabel ? <span>{visibleLabel}</span> : null}
      </>
    );

  if (appearance === "sentiment") {
    return (
      <SentimentBadge sentiment={sentiment} className={className}>
        {content}
      </SentimentBadge>
    );
  }

  return (
    <Badge
      data-grade={normalized ?? "ungraded"}
      variant={tone}
      size={size}
      as={as}
      shrink={shrink}
      className={className}
      {...props}
    >
      {content}
    </Badge>
  );
}

