  name: ReactNode;
  /** The line under the name, usually the current title. */
  headline?: ReactNode;
  /** The current-company line, rendered as given (it brings its own text). */
  company?: ReactNode;
  /** Media for the 4:1 cover frame. Omit it and no frame is drawn. */
  cover?: ReactNode;
