  selected: boolean;
  /** Called with no arguments; the host adds or removes the candidate. */
  onToggle: () => void;
  /** The accessible name, such as "Select Mei Tanaka". */
  label: string;
  /** The tooltip. Defaults to "Select", or "Deselect" while selected. */
  title?: string;
