import { Button } from "@epicbagel/saas-kit/primitives/button";
import { Popover, PopoverContent, PopoverTrigger } from "@epicbagel/saas-kit/primitives/popover";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type PointerEvent,
  type ReactNode,
} from "react";

import { CurrentCompanyLabel, type CurrentCompanyLabelProps } from "./current-company-label";

export interface CurrentCompanyPopoverProps
  extends Omit<CurrentCompanyLabelProps, "company" | "children"> {
  /** The company name. It becomes the trigger, a link-styled button. */
  company: ReactNode;
  /** The trigger's tooltip and accessible description, such as "View Example Co career history". */
  triggerTitle: string;
  /**
   * The popover's content. Called only while the popover is open, so a host
   * can load what it shows (a career history, say) on demand.
   */
  renderContent: () => ReactNode;
  /** How long the popover stays open after a mouse pointer leaves it. */
  closeDelayMs?: number;
}

/**
 * A current-company line whose company opens a popover: on hover for a
 * mouse, and on tap or click everywhere. Moving the mouse from the company
 * into the popover keeps it open; leaving both closes it after a short delay.
 *
 * Clicks on the trigger and inside the popover stop propagating, so the line
 * works inside a clickable candidate card. The content is mounted only while
 * the popover is open. The host supplies the tenure wording and the content;
 * the popover surface is marked `data-slot="current-company-popover"`.
 */
export function CurrentCompanyPopover({
  company,
  triggerTitle,
  renderContent,
  closeDelayMs = 180,
  size = "sm",
  tone = "muted",
  ...props
}: CurrentCompanyPopoverProps) {
  const [open, setOpen] = useState(false);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const cancelClose = useCallback(() => {
    if (closeTimer.current) clearTimeout(closeTimer.current);
    closeTimer.current = null;
  }, []);
  const scheduleClose = useCallback(() => {
    cancelClose();
    closeTimer.current = setTimeout(() => setOpen(false), closeDelayMs);
  }, [cancelClose, closeDelayMs]);
  useEffect(() => () => cancelClose(), [cancelClose]);

  const openOnMouse = (event: PointerEvent) => {
    if (event.pointerType !== "mouse") return;
    cancelClose();
    setOpen(true);
  };

  return (
    <CurrentCompanyLabel
      size={size}
      tone={tone}
      {...props}
      company={(
        <Popover open={open} onOpenChange={setOpen}>
          <PopoverTrigger asChild>
            <Button
              type="button"
              variant="link"
              size="bare"
              title={triggerTitle}
              onPointerEnter={openOnMouse}
              onPointerLeave={scheduleClose}
              onClick={(event) => event.stopPropagation()}
            >
              <Text variant="inherit" as="span" size={size} tone={tone} truncate>
                {company}
              </Text>
            </Button>
          </PopoverTrigger>
          {open && (
            <PopoverContent
              width="lg"
              data-slot="current-company-popover"
              onPointerEnter={cancelClose}
              onPointerLeave={scheduleClose}
              onClick={(event) => event.stopPropagation()}
            >
              {renderContent()}
            </PopoverContent>
          )}
        </Popover>
      )}
    />
  );
}

"use client";

import { Alert } from "@epicbagel/saas-kit/primitives/alert";
import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import { DocumentPreview, type DocumentPreviewProps } from "@epicbagel/saas-kit/primitives/document-preview";
import { EmptyState } from "@epicbagel/saas-kit/primitives/empty-state";
import { FileDropzone } from "@epicbagel/saas-kit/primitives/file-dropzone";
import { FlexItem } from "@epicbagel/saas-kit/primitives/flex-item";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { SectionHeader } from "@epicbagel/saas-kit/primitives/section-header";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@epicbagel/saas-kit/primitives/select";
import { Skeleton } from "@epicbagel/saas-kit/primitives/skeleton";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Download, Eye, File, Loader2, RefreshCw, Trash2 } from "lucide-react";
import {
  useEffect,
  useId,
  useRef,
  useState,
  type HTMLAttributes,
  type ReactNode,
} from "react";

import type { CandidateEmptyCopy } from "./candidate-empty-copy";
import { usePendingAction } from "./pending-action";

/**
 * How tightly a document list sits: `default` for a page or tab of its own,
 * `compact` for a section inside a pane, such as a person's detail pane.
 */
export type DocumentListDensity = "default" | "compact";

/** The kit Badge variant a document kind's badge takes. */
export type DocumentKindTone = "default" | "info" | "success" | "warning";

/** What kind of document a row holds, such as a CV or a role brief, as a badge. */
export interface DocumentKind {
  label: ReactNode;
  /** The badge's tone. Defaults to `default`. */
  tone?: DocumentKindTone;
}

/**
 * Formats a file size in bytes as "512 B", "180 KB" or "2.4 MB". A missing or
 * zero size reads as `empty` (an em dash by default).
 */
export function formatFileSize(bytes: number | null | undefined, empty = "—"): string {
  if (!bytes) return empty;
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

/** A row action, as `DocumentListItemLabels.actionName` receives it. */
export type DocumentListItemAction = "preview" | "download" | "reanalyse" | "delete";

export interface DocumentListItemLabels {
  /** The preview button's tooltip. */
  preview: string;
  /** The download button's tooltip. */
  download: string;
  /** The re-analyse button's tooltip. */
  reanalyse: string;
  /** The delete button's tooltip. */
  delete: string;
  /** Each action button's accessible name, for the file it acts on. */
  actionName: (action: DocumentListItemAction, name: string) => string;
  /** The button that confirms a delete. */
  confirmDelete: ReactNode;
  /** The button that backs out of a delete. */
  cancelDelete: ReactNode;
  /** Beside the spinner while the document is still being read. */
  processing: ReactNode;
}

const ACTION_VERB: Record<DocumentListItemAction, string> = {
  preview: "Preview",
  download: "Download",
  reanalyse: "Re-analyse",
  delete: "Delete",
};

const ITEM_LABELS: DocumentListItemLabels = {
  preview: "Preview document",
  download: "Download document",
  reanalyse: "Re-analyse document",
  delete: "Delete document",
  actionName: (action, name) => `${ACTION_VERB[action]} ${name}`,
  confirmDelete: "Delete",
  cancelDelete: "Cancel",
  processing: "Processing…",
};

export interface DocumentListItemProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  /** The file name. It is the row's title and names each action for screen readers. */
  name: string;
  /** What kind of document this is, as a badge after the name. */
  kind?: DocumentKind;
  /** A muted line beside the kind, such as the size and when it was added. */
  meta?: ReactNode;
  /** A short summary of what the document says, under the name. */
  summary?: ReactNode;
  /** Still being read: a spinner and `labels.processing` stand in for a missing `summary`. */
  processing?: boolean;
  /** Adds a preview button, such as for a file the host can show inline. */
  onPreview?: () => void;
  /** Adds a download button. A returned promise shows a spinner until it settles. */
  onDownload?: () => void | Promise<unknown>;
  /** Shows the download button's spinner, such as while another control downloads the file. */
  downloading?: boolean;
  /** Adds a re-analyse button. A returned promise shows a spinner until it settles. */
  onReanalyse?: () => void | Promise<unknown>;
  /** Shows the re-analyse button's spinner. */
  reanalysing?: boolean;
  /**
   * Adds a delete button, which asks to confirm in the row before calling
   * this. A returned promise disables the confirm button until it settles.
   */
  onDelete?: () => void | Promise<unknown>;
  density?: DocumentListDensity;
  labels?: Partial<DocumentListItemLabels>;
}

/**
 * One document: a file glyph, the name, its kind as a badge and the host's
 * `meta` line, then a summary or a processing state, with preview, download,
 * re-analyse and delete buttons for the callbacks given. Delete asks to
 * confirm in the row first. `compact` is one dense row for a pane; `default`
 * gives the summary the row's full width.
 *
 * The root is marked `data-slot="document-list-item"`.
 */
export function DocumentListItem({
  name,
  kind,
  meta,
  summary,
  processing = false,
  onPreview,
  onDownload,
  downloading = false,
  onReanalyse,
  reanalysing = false,
  onDelete,
  density = "default",
  labels,
  ...props
}: DocumentListItemProps) {
  const copy = { ...ITEM_LABELS, ...labels };
  const compact = density === "compact";
  const [confirming, setConfirming] = useState(false);
  const [downloadPending, download] = usePendingAction(onDownload);
  const [reanalysePending, reanalyse] = usePendingAction(onReanalyse);
  const [deletePending, remove] = usePendingAction(onDelete);
  const deleteRef = useRef<HTMLButtonElement>(null);
  const cancelRef = useRef<HTMLButtonElement>(null);
  const confirmed = useRef(false);

  // Keep focus with the row: on Cancel when the confirm opens, back on the
  // delete button when it closes.
  useEffect(() => {
    if (confirming) {
      confirmed.current = true;
      cancelRef.current?.focus();
    } else if (confirmed.current) {
      deleteRef.current?.focus();
    }
  }, [confirming]);

  const downloadBusy = downloading || downloadPending;
  const reanalyseBusy = reanalysing || reanalysePending;
  const iconSize = compact ? "xs" : "sm";
  const actionSize = compact ? "icon-xs" : "icon-compact";
  const confirmSize = compact ? "micro" : "compact";

  const kindBadge = kind ? (
    <Badge
      as="span"
      variant={kind.tone ?? "default"}
      size="micro-compact"
      shape="rounded"
      transform="uppercase"
    >
      {kind.label}
    </Badge>
  ) : null;
  const metaLine = meta != null && meta !== false && meta !== "" ? (
    <Text variant="micro" as="span" tone="muted">{meta}</Text>
  ) : null;

  const actions = confirming ? (
    <Stack direction="horizontal" gap="xs" align="center" shrink={false}>
      <Button
        type="button"
        size={confirmSize}
        variant="destructive"
        onClick={remove}
        disabled={deletePending}
      >
        {copy.confirmDelete}
      </Button>
      <Button
        ref={cancelRef}
        type="button"
        size={confirmSize}
        variant="ghost"
        onClick={() => setConfirming(false)}
      >
        {copy.cancelDelete}
      </Button>
    </Stack>
  ) : (
    <Stack direction="horizontal" gap={compact ? "lg" : "xs"} align="center" shrink={false}>
      {onPreview && (
        <Button
          type="button"
          size={actionSize}
          variant="ghost"
          onClick={() => onPreview()}
          title={copy.preview}
          aria-label={copy.actionName("preview", name)}
        >
          <Icon icon={Eye} size={iconSize} />
        </Button>
      )}
      {onDownload && (
        <Button
          type="button"
          size={actionSize}
          variant="ghost"
          onClick={download}
          disabled={downloadBusy}
          title={copy.download}
          aria-label={copy.actionName("download", name)}
        >
          {downloadBusy ? <Icon icon={Loader2} size={iconSize} spin /> : <Icon icon={Download} size={iconSize} />}
        </Button>
      )}
      {onReanalyse && (
        <Button
          type="button"
          size={actionSize}
          variant="ghost"
          onClick={reanalyse}
          disabled={reanalyseBusy}
          title={copy.reanalyse}
          aria-label={copy.actionName("reanalyse", name)}
        >
          {reanalyseBusy ? <Icon icon={Loader2} size={iconSize} spin /> : <Icon icon={RefreshCw} size={iconSize} />}
        </Button>
      )}
      {onDelete && (
        <Button
          ref={deleteRef}
          type="button"
          size={actionSize}
          variant="ghost"
          onClick={() => setConfirming(true)}
          title={copy.delete}
          aria-label={copy.actionName("delete", name)}
        >
          <Icon icon={Trash2} size={iconSize} />
        </Button>
      )}
    </Stack>
  );

  if (compact) {
    return (
      <Stack
        data-slot="document-list-item"
        direction="horizontal"
        gap="sm"
        align="start"
        surface="card"
        radius="md"
        padding="compact"
        {...props}
      >
        <Icon icon={File} size="sm" tone="muted" align="start" />
        <FlexItem grow minWidth="zero">
          <Stack direction="horizontal" gap="sm" wrap align="baseline">
            <Text variant="inherit" as="span" size="xs" weight="medium" truncate>{name}</Text>
            {kindBadge}
            {metaLine}
          </Stack>
          {summary ? (
            <Text size="micro" tone="muted" marginTop="tight" leading="snug">{summary}</Text>
          ) : processing ? (
            <Text size="micro" tone="muted" marginTop="tight" leading="snug" display="inline-flex">
              <Icon icon={Loader2} size="xs" spin />
              {copy.processing}
            </Text>
          ) : null}
        </FlexItem>
        {actions}
      </Stack>
    );
  }

  return (
    <Stack data-slot="document-list-item" gap="sm" surface="card" radius="md" padding="compact" {...props}>
      <Stack direction="horizontal" gap="sm" align="start">
        <Icon icon={File} size="md" tone="muted" align="start" />
        <FlexItem grow minWidth="zero">
          <Text variant="inherit" as="p" size="sm" weight="medium" truncate>{name}</Text>
          {kindBadge || metaLine ? (
            <Stack direction="horizontal" gap="sm" wrap align="baseline" marginTop="xs">
              {kindBadge}
              {metaLine}
            </Stack>
          ) : null}
        </FlexItem>
        {actions}
      </Stack>
      {summary ? (
        <Text size="xs" tone="muted">{summary}</Text>
      ) : processing ? (
        <Text size="xs" tone="muted" display="inline-flex">
          <Icon icon={Loader2} size="xs" spin />
          {copy.processing}
        </Text>
      ) : null}
    </Stack>
  );
}

export interface DocumentListProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  /**
   * How many documents there are. Zero shows the empty state in place of the
   * rows. Left out, such as before the first load succeeds, the list shows
   * only what `children` holds.
   */
  count?: number;
  /** A skeleton row in place of the list. */
  loading?: boolean;
  /** The blank slate's wording. Defaults to "No documents yet". */
  empty?: CandidateEmptyCopy;
  density?: DocumentListDensity;
  /** The documents, usually DocumentListItems with the same `density`. */
  children?: ReactNode;
}

/**
 * The documents one after another: a skeleton row while they load, the
 * host's rows, or the kit's empty state when there are none.
 *
 * The root is marked `data-slot="document-list"`.
 */
export function DocumentList({
  count,
  loading = false,
  empty = { title: "No documents yet" },
  density = "default",
  children,
  ...props
}: DocumentListProps) {
  const compact = density === "compact";
  return (
    <Stack data-slot="document-list" direction="vertical" gap={compact ? "xs" : "sm"} {...props}>
      {loading ? (
        <Skeleton preset={compact ? "control" : "row"} />
      ) : count === 0 ? (
        <EmptyState
          variant="empty"
          size="inline"
          icon={File}
          title={empty.title}
          // Without host wording, no description: the kit's generic one
          // ("Get started by creating...") doesn't fit a document list.
          description={empty.description ?? ""}
        />
      ) : (
        children
      )}
    </Stack>
  );
}

/** One kind a new upload can be filed as. */
export interface DocumentKindOption<TValue extends string = string> {
  value: TValue;
  label: ReactNode;
}

/** The kind the next upload is filed as, picked in the panel's header. */
export interface DocumentKindSelect<TValue extends string = string> {
  value: TValue;
  options: readonly DocumentKindOption<TValue>[];
  onValueChange: (value: TValue) => void;
}

export interface DocumentUploadPanelLabels {
  /** The drop zone's main line. */
  dropzone: ReactNode;
  /** A muted line under it, such as what happens to an upload. */
  dropzoneDescription?: ReactNode;
  /** The drop zone's line while `uploading`, such as how many files are on their way. */
  uploading: ReactNode;
  /** The kind select's accessible name. */
  kind: string;
}

const PANEL_LABELS: DocumentUploadPanelLabels = {
  dropzone: "Drop documents, or choose files",
  uploading: "Uploading…",
  kind: "Document kind",
};

export interface DocumentUploadPanelProps<TValue extends string = string>
  extends Omit<HTMLAttributes<HTMLElement>, "title" | "children"> {
  /** The section heading. Defaults to "Documents". */
  title?: ReactNode;
  /**
   * How many documents there are, as DocumentList takes it. The compact
   * header shows it beside the title while it is above zero.
   */
  count?: number;
  /** A skeleton row in place of the list, and no count yet. */
  loading?: boolean;
  /** A failed load, upload or delete, above the drop zone. */
  error?: ReactNode;
  /** Called with the files a person drops or picks; the host uploads them. */
  onFiles: (files: File[]) => void | Promise<void>;
  /** Shows the drop zone busy, with `labels.uploading`. */
  uploading?: boolean;
  /** The file types the picker offers, as the input's `accept`. */
  accept?: string;
  /** Adds a select to the header for the kind the next upload is filed as. */
  kindSelect?: DocumentKindSelect<TValue>;
  /** The blank slate's wording. Defaults to "No documents yet". */
  empty?: CandidateEmptyCopy;
  density?: DocumentListDensity;
  /** The compact panel's divider, as the kit PanelSection takes it. Defaults to `bottom`. */
  border?: "none" | "top" | "bottom";
  labels?: Partial<DocumentUploadPanelLabels>;
  /** Controlled document preview. The host owns URL loading, authorization and download callbacks. */
  preview?: DocumentPreviewProps;
  /** The documents, usually DocumentListItems with the same `density`. */
  children?: ReactNode;
}

/**
 * A documents section: a heading, an optional select for the kind of the
 * next upload, an error, the kit's drop zone and the DocumentList under it.
 * The host uploads what is dropped, loads the list and renders each row.
 * `compact` is a counted section with a divider for a pane; `default` is a
 * padded section for a page or tab of its own.
 *
 * The root is a section named by its title and marked
 * `data-slot="document-upload-panel"`.
 */
export function DocumentUploadPanel<TValue extends string = string>({
  title = "Documents",
  count,
  loading = false,
  error,
  onFiles,
  uploading = false,
  accept,
  kindSelect,
  empty,
  density = "default",
  border = "bottom",
  labels,
  preview,
  children,
  ...props
}: DocumentUploadPanelProps<TValue>) {
  const copy = { ...PANEL_LABELS, ...labels };
  const compact = density === "compact";
  const titleId = useId();

  const select = kindSelect ? (
    <Select
      value={kindSelect.value}
      onValueChange={(next) => kindSelect.onValueChange(next as TValue)}
    >
      <SelectTrigger
        controlSize="sm"
        textSize="xs"
        width="sm"
        aria-label={copy.kind}
        data-slot="document-kind-select"
      >
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {kindSelect.options.map((option) => (
          <SelectItem key={option.value} value={option.value} size="xs">
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  ) : null;

  const dropzone = (
    <FileDropzone
      multiple
      onFiles={onFiles}
      busy={uploading}
      accept={accept}
      label={copy.dropzone}
      busyLabel={copy.uploading}
      description={copy.dropzoneDescription}
    />
  );

  const list = (
    <DocumentList count={count} loading={loading} empty={empty} density={density}>
      {children}
    </DocumentList>
  );

  if (compact) {
    return (
      <PanelSection
        data-slot="document-upload-panel"
        aria-labelledby={titleId}
        border={border}
        {...props}
      >
        <SectionHeader
          id={titleId}
          label={title}
          count={!loading && count ? count : undefined}
          action={select}
        />
        {error ? (
          <Alert variant="destructive" radius="md" padding="compact" textSize="xs" marginBottom="md">
            {error}
          </Alert>
        ) : null}
        {dropzone}
        <Stack marginTop="sm">{list}</Stack>
        {preview && <DocumentPreview {...preview} />}
      </PanelSection>
    );
  }

  return (
    <Stack
      as="section"
      data-slot="document-upload-panel"
      aria-labelledby={titleId}
      gap="md"
      padding="md"
      {...props}
    >
      <Stack direction="horizontal" justify="between" align="center">
        <Text id={titleId} as="h2" variant="inherit" size="sm" weight="semibold">{title}</Text>
        {select}
      </Stack>
      {error ? (
        <Alert variant="destructive" radius="md" padding="compact" textSize="xs">
          {error}
        </Alert>
      ) : null}
      {dropzone}
      {list}
      {preview && <DocumentPreview {...preview} />}
    </Stack>
  );
}

"use client";

import { Alert, AlertDescription } from "@epicbagel/saas-kit/primitives/alert";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import { Card } from "@epicbagel/saas-kit/primitives/card";
import { CollapsibleSection } from "@epicbagel/saas-kit/primitives/collapsible-section";
import { DefinitionItem, DefinitionList } from "@epicbagel/saas-kit/primitives/definition-list";
import { EditableList } from "@epicbagel/saas-kit/primitives/editable-list";
import { EmptyState } from "@epicbagel/saas-kit/primitives/empty-state";
import { Heading } from "@epicbagel/saas-kit/primitives/heading";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { List, ListItem } from "@epicbagel/saas-kit/primitives/list";
import type { Sentiment } from "@epicbagel/saas-kit/primitives/sentiment-dot";
import { Skeleton } from "@epicbagel/saas-kit/primitives/skeleton";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { StatusBadge } from "@epicbagel/saas-kit/primitives/status-badge";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { FileText, Loader2 } from "lucide-react";
import { useEffect, useId, useRef, useState, type HTMLAttributes, type ReactNode } from "react";

import type { CandidateEmptyCopy } from "./candidate-empty-copy";
import {
  jobBriefLabels,
  jobBriefVersionLabel,
  type JobBriefRuleKind,
  type JobBriefRuleLabels,
  type JobBriefVersion,
} from "./job-brief-view";
import { usePendingCall } from "./pending-action";
import { COARSE_POINTER_TOUCH_TARGET, COARSE_POINTER_TOUCH_TARGETS_WITHIN } from "./touch-targets";

// The brief's content helpers and wording live in a module without a client
// boundary, so a server component can map a brief too; they are re-exported
// here, beside the card that shows what they return.
export * from "./job-brief-view";

/**
 * How a JobBriefCard sits. `collapsible` is a card whose whole body folds
 * under its title, for a section of a page. `preview` is a card that shows
 * the start of the brief and opens the rest in place, for a message in a
 * conversation.
 */
export type JobBriefCardPresentation = "collapsible" | "preview";

/** One labelled fact about a role, such as its location or salary, worded by the host. */
export interface JobBriefFact {
  /** Stable key for the row. */
  id: string;
  label: ReactNode;
  value: ReactNode;
}

/**
 * A titled part of the brief after the three lists, such as the role's
 * details, who it sells to, or the interview process. It holds facts, items,
 * or both; a section with neither isn't drawn.
 */
export interface JobBriefSection {
  /** Stable key for the section. */
  id: string;
  /** The section's heading, such as "Role details". */
  title: ReactNode;
  /** Labelled facts, drawn as a divided list. */
  facts?: readonly JobBriefFact[];
  /** Entries drawn as a bulleted list, or a numbered one with `ordered`. */
  items?: readonly ReactNode[];
  /** Number the items, such as for the steps of an interview process. */
  ordered?: boolean;
}

/**
 * Host-owned wording for a JobBriefCard's states and toggle. The lists' names
 * are the brief's wording, not the host's: they come in `ruleLabels`.
 */
export interface JobBriefCardLabels {
  /** The notice over a brief that is still being read from a document. */
  processing: ReactNode;
  /** The in-progress blank slate's title, while nothing has been read yet. */
  processingTitle: string;
  /** The in-progress blank slate's description, under its title. */
  processingDescription: string;
  /**
   * The preview's toggle while part of the brief is hidden. It receives how
   * many facts, list entries and section rows are hidden (zero when only the
   * editing controls are).
   */
  showMore: (hidden: number) => ReactNode;
  /** The preview's toggle while the whole brief is shown. */
  showLess: ReactNode;
}

const DEFAULT_LABELS: JobBriefCardLabels = {
  processing: "Reading your document. The brief will fill in shortly.",
  processingTitle: "Reading your document",
  processingDescription: "The brief will fill in shortly.",
  showMore: (hidden) => (hidden > 0 ? `Show full brief (${hidden} more)` : "Show full brief"),
  showLess: "Show less",
};

export interface JobBriefCardProps
  extends Omit<HTMLAttributes<HTMLElement>, "title" | "children"> {
  /** `collapsible` (the default) for a page, `preview` for a message. */
  presentation?: JobBriefCardPresentation;
  /**
   * The brief's title, such as `jobBriefView`'s. With the status, it names the
   * section. Defaults to "Job brief".
   */
  title?: ReactNode;
  /**
   * The title's heading level: 2 (the default), or 3 or 4 where the card sits
   * deeper in the page's outline. Only the tags change, never the look. In
   * `preview` the title is a heading at this level and the lists' and
   * sections' headings sit one level below it. In `collapsible` the title is
   * the kit CollapsibleSection's trigger, which can't hold a heading, so the
   * lists' and sections' headings take this level themselves and the outline
   * skips none.
   */
  titleLevel?: 2 | 3 | 4;
  /**
   * At the title's end, such as an "Updated" badge, in the same place in both
   * presentations, after the `version`. It keeps its width: on a narrow
   * screen the title wraps rather than the status. It names the section with
   * the title ("… Updated"), so briefs stay apart in a screen reader's list
   * of regions. In `collapsible` it sits inside the trigger button, so pass
   * phrasing content (a Badge rendered `as="span"`).
   */
  status?: ReactNode;
  /**
   * Which version of the brief this is, drawn at the title's end before any
   * `status`, as the kit StatusBadge: `jobBriefVersionLabel`'s wording ("v3 ·
   * Current" or "v2 · Earlier", or the version's own `label`), in the success
   * tone on the version in force now and the neutral tone on an earlier one,
   * then any `secondaryLabel` in a second, neutral badge. Like the status, it
   * names the section with the title ("… v3 · Current"), so each version
   * stays apart from the others.
   */
  version?: JobBriefVersion;
  /** What the role is, in a sentence or two. Clamped to two lines in a closed preview. */
  description?: ReactNode;
  /** Headline facts after the description, such as location, salary and on-target earnings. */
  facts?: readonly JobBriefFact[];
  mustHaves?: readonly string[];
  niceToHaves?: readonly string[];
  redFlags?: readonly string[];
  /**
   * Which lists show, in order. Defaults to all three. Whether a page shows
   * its red flags is the host's call: leave `redFlags` out of `rules` where
   * they mustn't be seen.
   */
  rules?: readonly JobBriefRuleKind[];
  /**
   * Given, the lists are editable in place: each add, edit or remove hands
   * the whole new list to the host, with which list it is. The lists stay
   * controlled: they show the host's arrays. If the callback returns a
   * promise, the list shows what it sent, marked busy, until the promise
   * settles, then the host's arrays again, so a save that fails reverts and
   * the host says why. Resolve once the arrays reflect the save.
   */
  onRulesChange?: (kind: JobBriefRuleKind, items: string[]) => void | PromiseLike<unknown>;
  /** Titled parts after the lists, in order, such as role details, buyers, interview steps and the company. */
  sections?: readonly JobBriefSection[];
  /**
   * Last, such as example candidates or an action. In `collapsible` it folds
   * with the body; in `preview` it shows in both states, under the toggle.
   */
  footer?: ReactNode;
  /**
   * The brief is still being read from a document. With nothing to show and
   * nothing to edit yet, an in-progress blank slate stands in for the body;
   * otherwise a notice sits above it, so an editable brief keeps its lists
   * and add fields however long the reading takes.
   */
  processing?: boolean;
  /** Skeleton rows in place of a body that has nothing to show yet. */
  loading?: boolean;
  /** Whether the body is open: the collapsible's body, or the preview's full brief. */
  open?: boolean;
  /** Whether the body starts open when `open` is left to the card. Defaults to false. */
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /**
   * In a closed preview, how many facts and how many entries of the first
   * shown list with any show. Defaults to 3; 0 leaves the title, the
   * description and the toggle.
   */
  previewCount?: number;
  /**
   * The blank slate's wording when there is nothing to show and nothing to
   * edit. Defaults to "No brief yet".
   */
  empty?: CandidateEmptyCopy;
  /**
   * The lists' names and what one entry of each is called in their controls
   * ("Add must-have…", "Remove must-have"), such as `jobBriefView`'s. Defaults
   * to `jobBriefLabels`' wording.
   */
  ruleLabels?: Partial<JobBriefRuleLabels>;
  labels?: Partial<JobBriefCardLabels>;
}

const RULE_KINDS: readonly JobBriefRuleKind[] = ["mustHaves", "niceToHaves", "redFlags"];
const NO_ITEMS: readonly string[] = [];
const NO_FACTS: readonly JobBriefFact[] = [];
const NO_SECTIONS: readonly JobBriefSection[] = [];

const SENTIMENT: Record<JobBriefRuleKind, Sentiment> = {
  mustHaves: "positive",
  niceToHaves: "warning",
  redFlags: "negative",
};

const ITEM_NAME: Record<JobBriefRuleKind, "mustHaveItem" | "niceToHaveItem" | "redFlagItem"> = {
  mustHaves: "mustHaveItem",
  niceToHaves: "niceToHaveItem",
  redFlags: "redFlagItem",
};

// The collapsible's trigger and body take the preview's inset (the kit Card's
// `md` padding) and its 16px between the title row and the body, so the two
// presentations line up and differ only in what folds. The trigger stays the
// whole row, with the chevron 16px after the status. It drops the kit
// trigger's small type, whose line height the status would otherwise take,
// so a badge there is as tall as in the preview.
const COLLAPSIBLE_TRIGGER = "gap-4 p-[26px] text-[length:inherit] data-[state=open]:pb-4";
const COLLAPSIBLE_BODY = "px-[26px] pb-[26px]";

// The kit EditableList's own label, so a section reads as one more list.
const SECTION_LABEL = "text-xs font-medium uppercase tracking-wider";

// The kit list shows a row's edit and remove buttons on hover or focus only,
// which a touchscreen never has: there they stay visible, at the 44px a
// finger needs, with the fields beside them as tall. The shared bullet row
// owns first-line alignment and the same minimum height for read-only rows.
const EDITABLE_LIST = [
  "pointer-coarse:[&_button]:opacity-100",
  "pointer-coarse:[&_input]:min-h-[max(44px,2.75rem)]",
  COARSE_POINTER_TOUCH_TARGETS_WITHIN,
].join(" ");

type SubheadingLevel = 2 | 3 | 4 | 5;

function present(value: ReactNode): boolean {
  return value != null && value !== false && value !== "";
}

function sectionRows(section: JobBriefSection): number {
  return (section.facts?.length ?? 0) + (section.items?.length ?? 0);
}

/** The version's badges: its wording, then any second label. */
function versionBadges(version: JobBriefVersion | undefined): ReactNode {
  if (!version) return null;
  const secondary = version.secondaryLabel?.trim();
  return (
    // Phrasing content throughout, so it can sit in the collapsible's trigger.
    <Stack
      as="span"
      data-slot="job-brief-version"
      data-current={version.current ? "true" : "false"}
      direction="horizontal"
      gap="xs"
      align="center"
    >
      <StatusBadge as="span" tone={version.current ? "success" : "neutral"}>{jobBriefVersionLabel(version)}</StatusBadge>
      {secondary ? <StatusBadge as="span" tone="neutral">{secondary}</StatusBadge> : null}
    </Stack>
  );
}

/**
 * The title row both presentations share: the title in the kit's card-title
 * type, and the version and status at its end. Given a heading tag, the
 * title is that heading; without one the row is the collapsible trigger's
 * label, so every part is a span (a button holds only phrasing content).
 */
function BriefHeader({
  title,
  status,
  version,
  titleId,
  statusId,
  heading,
}: {
  title: ReactNode;
  status: ReactNode;
  version: ReactNode;
  titleId: string;
  statusId: string;
  heading?: "h2" | "h3" | "h4";
}) {
  const as = heading ? "div" : "span";
  const hasStatus = present(status);
  return (
    // In the trigger the row takes the width the chevron leaves.
    <Stack as={as} direction="horizontal" gap="md" align="start" justify="between" grow={!heading} minWidth="zero">
      <Stack as={as} grow minWidth="zero">
        {/* The card-title look at every level. */}
        <Heading id={titleId} level={3} as={heading ?? "span"}>{title}</Heading>
      </Stack>
      {/* A badge would shrink and wrap before the title does. */}
      {version ? (
        <Stack as={as} id={statusId} shrink={false} direction="horizontal" gap="xs" align="center">
          {version}
          {hasStatus ? status : null}
        </Stack>
      ) : hasStatus ? (
        <Stack as={as} id={statusId} shrink={false}>{status}</Stack>
      ) : null}
    </Stack>
  );
}

function BriefFacts({ facts, bordered }: { facts: readonly JobBriefFact[]; bordered?: boolean }) {
  return (
    <DefinitionList variant="divided" className={bordered ? "border-t" : undefined}>
      {facts.map((fact) => (
        <DefinitionItem key={fact.id} label={fact.label}>{fact.value}</DefinitionItem>
      ))}
    </DefinitionList>
  );
}

function RuleList({
  kind,
  items,
  label,
  itemName,
  level,
  onRulesChange,
}: {
  kind: JobBriefRuleKind;
  items: readonly string[];
  label: string;
  itemName: string;
  level: SubheadingLevel;
  onRulesChange?: (kind: JobBriefRuleKind, items: string[]) => unknown;
}) {
  const [pending, save, sent] = usePendingCall(onRulesChange);
  const shown = pending && sent ? sent[1] : items;

  // A read-only list with nothing in it draws nothing, as the kit list does.
  if (!onRulesChange && shown.length === 0) return null;

  return (
    <Stack data-slot="job-brief-rule-list" data-kind={kind} aria-busy={pending || undefined} gap="none">
      <EditableList
        label={<span role="heading" aria-level={level}>{label}</span>}
        itemName={itemName}
        sentiment={SENTIMENT[kind]}
        items={[...shown]}
        onChange={onRulesChange ? (next) => save(kind, next) : undefined}
        className={onRulesChange ? EDITABLE_LIST : undefined}
      />
    </Stack>
  );
}

function BriefSection({ section, level }: { section: JobBriefSection; level: SubheadingLevel }) {
  const facts = section.facts ?? NO_FACTS;
  const items = section.items ?? [];
  if (facts.length === 0 && items.length === 0) return null;

  return (
    <Stack data-slot="job-brief-section" border="top" paddingTop="base" gap="compact">
      {/* A heading holding the kit list's label, so it lines up with the lists'. */}
      <Text as={`h${level}`} variant="inherit">
        <Text as="span" variant="caption" className={SECTION_LABEL}>{section.title}</Text>
      </Text>
      {facts.length > 0 ? <BriefFacts facts={facts} /> : null}
      {items.length > 0 ? (
        // The same kit bullet row, and spacing, a read-only EditableList uses
        // for the requirements: rows about 1.8em apart.
        <List
          ordered={section.ordered}
          marker={section.ordered ? "decimal" : "none"}
          spacing="tight"
          textSize="sm"
        >
          {items.map((item, index) => (
            <ListItem key={index} layout={section.ordered ? "plain" : "bullet"}>{item}</ListItem>
          ))}
        </List>
      ) : null}
    </Stack>
  );
}

/**
 * A job brief: what the role is, its headline facts, the must-have,
 * nice-to-have and red-flag lists, then titled sections such as role details
 * or the interview process, and a footer slot. Every value enters as a
 * display value or a slot, worded by the host; `jobBriefView` maps a brief's
 * fields onto them, so one brief reads the same in every host.
 *
 * Two presentations share one look: the same title row (the title in the
 * card-title type, the version and status at its end), inset and body, and
 * differ only in what folds. `collapsible` is a kit Card holding a
 * CollapsibleSection, for a page: the title row is the trigger and the whole
 * body folds under it. `preview` is a kit Card with the title as a heading,
 * for a message: closed, it shows the description (two lines), the first
 * `previewCount` facts and entries of the first shown list that has any,
 * then a toggle that opens the full brief in place; with nothing hidden, the
 * full brief shows and no toggle does. Closing it from the toggle brings the
 * card back into view, since a long brief's toggle sits far below its top.
 *
 * Given `onRulesChange`, the lists are editable in place, and saving stays
 * with the host. A read-only empty list draws nothing; an editable one keeps
 * the kit's "None set" and its add field, also while `processing`, under the
 * notice. A read-only brief with nothing to show is the kit's empty state,
 * or an in-progress one while `processing`; while `loading`, skeleton rows.
 *
 * Given a `version`, its badges lead the status: "v3 · Current" in the
 * success tone, or "v2 · Earlier" in the neutral one (`jobBriefVersionLabel`),
 * and any second label beside it, neutral.
 *
 * The root is a `section` named by the title, the version and the status
 * together, and marked `data-slot="job-brief-card"`, with
 * `data-presentation`; the version's badges are marked
 * `data-slot="job-brief-version"` with `data-current`, each list's wrapper
 * `data-slot="job-brief-rule-list"` with its `data-kind`, each section
 * `data-slot="job-brief-section"`, and the skeleton
 * `data-slot="job-brief-loading"`. The kit Card and badges inside keep their
 * own.
 */
export function JobBriefCard({
  presentation = "collapsible",
  title = jobBriefLabels.title,
  titleLevel = 2,
  status,
  version,
  description,
  facts = NO_FACTS,
  mustHaves = NO_ITEMS,
  niceToHaves = NO_ITEMS,
  redFlags = NO_ITEMS,
  rules = RULE_KINDS,
  onRulesChange,
  sections = NO_SECTIONS,
  footer,
  processing = false,
  loading = false,
  open,
  defaultOpen = false,
  onOpenChange,
  previewCount = 3,
  empty = { title: "No brief yet" },
  ruleLabels,
  labels,
  ...props
}: JobBriefCardProps) {
  const text = { ...DEFAULT_LABELS, ...labels };
  const ruleText: JobBriefRuleLabels = { ...jobBriefLabels, ...ruleLabels };
  const titleId = useId();
  const statusId = useId();
  const bodyId = useId();
  const versionStatus = versionBadges(version);
  // The section is named by its title, its version and its status together.
  const labelledBy = versionStatus || present(status) ? `${titleId} ${statusId}` : titleId;
  const header = (heading?: "h2" | "h3" | "h4") => (
    <BriefHeader
      title={title}
      status={status}
      version={versionStatus}
      titleId={titleId}
      statusId={statusId}
      heading={heading}
    />
  );
  const [openState, setOpenState] = useState(defaultOpen);
  const expanded = open ?? openState;
  const setExpanded = (next: boolean) => {
    if (open === undefined) setOpenState(next);
    onOpenChange?.(next);
  };
  // A preview closed from its toggle, which sat at the foot of the full
  // brief: once it has closed, bring the card back into view, or the reader
  // is left far below it. "nearest" leaves a card that is in view alone.
  const returnTo = useRef<HTMLElement | null>(null);
  useEffect(() => {
    const card = returnTo.current;
    if (expanded || !card) return;
    returnTo.current = null;
    if (typeof card.scrollIntoView === "function") card.scrollIntoView({ block: "nearest" });
  }, [expanded]);

  const lists: Record<JobBriefRuleKind, readonly string[]> = { mustHaves, niceToHaves, redFlags };
  const shownRules = rules.filter((kind, index) => RULE_KINDS.includes(kind) && rules.indexOf(kind) === index);
  const editable = onRulesChange != null;
  // A collapsible's title is a button, not a heading, so its lists' and
  // sections' headings take the title's level rather than skip one.
  const subLevel = (presentation === "collapsible" ? titleLevel : titleLevel + 1) as SubheadingLevel;
  const hasDescription = present(description);
  const hasContent =
    hasDescription ||
    facts.length > 0 ||
    shownRules.some((kind) => lists[kind].length > 0) ||
    sections.some((section) => sectionRows(section) > 0);
  // An editable brief always keeps its lists, so the host's only way to add
  // rules never waits on a document that may never finish being read.
  const state = hasContent
    ? "content"
    : loading
      ? "loading"
      : editable
        ? "content"
        : processing
          ? "processing"
          : "empty";

  const blank =
    state === "loading" ? (
      <Stack data-slot="job-brief-loading" aria-busy gap="sm">
        <Skeleton preset="line-full" />
        <Skeleton preset="line-wide" />
        <Skeleton preset="row-compact" />
        <Skeleton preset="row-compact" />
      </Stack>
    ) : state === "processing" ? (
      <EmptyState
        variant="empty"
        size="inline"
        icon={Loader2}
        iconMotion="spin"
        title={text.processingTitle}
        description={text.processingDescription}
      />
    ) : state === "empty" ? (
      <EmptyState
        variant="empty"
        size="inline"
        icon={FileText}
        title={empty.title}
        // Without host wording, no description: the kit's generic one ("Get
        // started by creating...") doesn't fit a brief.
        description={empty.description ?? ""}
      />
    ) : null;

  const notice = processing ? (
    <Alert>
      <Icon icon={Loader2} size="sm" spin />
      <AlertDescription>{text.processing}</AlertDescription>
    </Alert>
  ) : null;

  const ruleList = (kind: JobBriefRuleKind, items: readonly string[], canEdit: boolean) => (
    <RuleList
      key={kind}
      kind={kind}
      items={items}
      label={ruleText[kind]}
      itemName={ruleText[ITEM_NAME[kind]]}
      level={subLevel}
      onRulesChange={canEdit ? onRulesChange : undefined}
    />
  );

  const fullBody = (
    <>
      {notice}
      {hasDescription ? <Text as="div" variant="caption">{description}</Text> : null}
      {facts.length > 0 ? <BriefFacts facts={facts} bordered /> : null}
      {shownRules.map((kind) => ruleList(kind, lists[kind], editable))}
      {sections.map((section) => (
        <BriefSection key={section.id} section={section} level={subLevel} />
      ))}
    </>
  );

  if (presentation === "collapsible") {
    return (
      <Stack
        as="section"
        data-slot="job-brief-card"
        data-presentation="collapsible"
        aria-labelledby={labelledBy}
        gap="none"
        {...props}
      >
        <Card>
          <CollapsibleSection
            title={header()}
            open={open}
            defaultOpen={defaultOpen}
            onOpenChange={onOpenChange}
            density="roomy"
            divided={false}
            inset="none"
            triggerClassName={COLLAPSIBLE_TRIGGER}
            contentClassName={COLLAPSIBLE_BODY}
          >
            {blank ?? fullBody}
            {state === "loading" ? null : footer}
          </CollapsibleSection>
        </Card>
      </Stack>
    );
  }

  // The preview: what is left out while it is closed. Its list is the first
  // one with entries, so an empty must-haves list doesn't leave it bare.
  const count = Math.max(0, Math.floor(previewCount));
  const first = shownRules.find((kind) => lists[kind].length > 0) ?? shownRules[0];
  const hidden =
    Math.max(0, facts.length - count) +
    shownRules.reduce(
      (sum, kind) => sum + (kind === first ? Math.max(0, lists[kind].length - count) : lists[kind].length),
      0,
    ) +
    sections.reduce((sum, section) => sum + sectionRows(section), 0);
  // Editing happens in the full brief, so an editable preview always offers it.
  const hasToggle = state === "content" && (hidden > 0 || editable);
  const full = !hasToggle || expanded;
  // Closed with nothing to show before the toggle (no description, and a
  // `previewCount` of 0 or nothing to count), there is no body, so the toggle
  // sits one gap under the title row, not two. Nothing points at it: the
  // toggle's `aria-controls` is set only while open.
  const hasBody =
    full ||
    notice !== null ||
    hasDescription ||
    (count > 0 && (facts.length > 0 || (first !== undefined && lists[first].length > 0)));

  return (
    <Stack
      as="section"
      data-slot="job-brief-card"
      data-presentation="preview"
      aria-labelledby={labelledBy}
      gap="none"
      {...props}
    >
      <Card padding="md">
        <Stack gap="md">
          {header(`h${titleLevel}`)}
          {blank ??
            (hasBody ? (
              <Stack id={bodyId} gap="md">
                {full ? (
                  fullBody
                ) : (
                  <>
                    {notice}
                    {hasDescription ? (
                      <Text as="div" variant="caption" lineClamp={2}>{description}</Text>
                    ) : null}
                    {count > 0 && facts.length > 0 ? <BriefFacts facts={facts.slice(0, count)} bordered /> : null}
                    {count > 0 && first ? ruleList(first, lists[first].slice(0, count), false) : null}
                  </>
                )}
              </Stack>
            ) : null)}
          {hasToggle ? (
            <Stack direction="horizontal" gap="none">
              <Button
                type="button"
                variant="link-muted"
                size="bare"
                align="start"
                aria-expanded={expanded}
                aria-controls={expanded ? bodyId : undefined}
                onClick={(event) => {
                  if (expanded) {
                    returnTo.current = event.currentTarget.closest<HTMLElement>('[data-slot="job-brief-card"]');
                  }
                  setExpanded(!expanded);
                }}
                className={COARSE_POINTER_TOUCH_TARGET}
              >
                {expanded ? text.showLess : text.showMore(hidden)}
              </Button>
            </Stack>
          ) : null}
          {state === "loading" ? null : footer}
        </Stack>
      </Card>
    </Stack>
  );
}

"use client";

import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import {
  Trace,
  TraceCollapsible,
  TraceCollapsibleContent,
  TraceCollapsibleTrigger,
  TraceIcon,
  TraceLine,
} from "@epicbagel/saas-kit/primitives/trace";
import { ArrowRight, ArrowUpDown, Minus, Plus, RefreshCw, type LucideIcon } from "lucide-react";
import type { HTMLAttributes } from "react";

import {
  jobBriefChangeLabels,
  jobBriefChangeText,
  type JobBriefChange,
  type JobBriefChangeKind,
  type JobBriefChangeLabels,
} from "./job-brief-view";

// The change wording lives in a module without a client boundary, so a
// server can word a change too; it is re-exported here, beside the list
// that shows it.
export {
  jobBriefChangeLabels,
  jobBriefChangeText,
  type JobBriefChange,
  type JobBriefChangeKind,
  type JobBriefChangeLabels,
  type JobBriefChangeValue,
} from "./job-brief-view";

export interface JobBriefChangesProps extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /**
   * What the version changed, in the order it was made, as display values:
   * map your own record of each change onto `JobBriefChange`.
   */
  changes: readonly JobBriefChange[];
  /** The version these changes made, which names the group ("What changed in v3"). */
  version?: number;
  /** How many changes show before the rest fold under "N more changes". Defaults to 3. */
  previewCount?: number;
  /** Any of the wording in `jobBriefChangeLabels`: the lines, the toggle and the group's name. */
  labels?: Partial<JobBriefChangeLabels>;
}

/**
 * The icon each kind of change leads with. No sentiment colour: the brief
 * already colours its lists, and a removal isn't bad news. The line's own
 * words ("Added …", "Removed …") say what the icon shows.
 */
const CHANGE_ICONS: Record<JobBriefChangeKind, LucideIcon> = {
  added: Plus,
  removed: Minus,
  cleared: Minus,
  reworded: ArrowRight,
  set: ArrowRight,
  moved: ArrowUpDown,
  replaced: RefreshCw,
};

const DEFAULT_PREVIEW_COUNT = 3;

function ChangeLine({ change, labels }: { change: JobBriefChange; labels: JobBriefChangeLabels }) {
  return (
    <TraceLine data-change-kind={change.kind}>
      <TraceIcon>
        {/* A kind this release doesn't know reads as a change of value. */}
        <Icon icon={CHANGE_ICONS[change.kind] ?? ArrowRight} />
      </TraceIcon>
      <Text as="span" variant="inherit" minWidth="zero">{jobBriefChangeText(change, labels)}</Text>
    </TraceLine>
  );
}

/**
 * What a version of a brief changed, for under its JobBriefCard: one quiet
 * line per change, in the kit's trace lines, each leading with an icon for
 * its kind (added, removed or cleared, set or reworded, moved, replaced) and
 * worded by `jobBriefChangeText`. The first `previewCount` show; the rest
 * fold under a "N more changes" toggle that opens them in place. A version
 * with no changes to list (the first, which is the whole brief) draws
 * nothing.
 *
 * The root is a group named for the version ("What changed in v3"), so a
 * screen reader tells versions apart, and marked
 * `data-slot="job-brief-changes"`; each line carries its `data-change-kind`.
 * The kit's trace parts inside keep their own `data-slot`.
 */
export function JobBriefChanges({
  changes,
  version,
  previewCount = DEFAULT_PREVIEW_COUNT,
  labels,
  ...props
}: JobBriefChangesProps) {
  if (changes.length === 0) return null;
  const words: JobBriefChangeLabels = { ...jobBriefChangeLabels, ...labels };
  const count = Number.isFinite(previewCount) ? Math.max(0, Math.floor(previewCount)) : DEFAULT_PREVIEW_COUNT;
  const lines = changes.map((change, index) => ({ key: change.id ?? String(index), change }));
  const shown = lines.slice(0, count);
  const folded = lines.slice(count);

  return (
    <Stack data-slot="job-brief-changes" role="group" aria-label={words.groupName(version)} gap="none" {...props}>
      <Trace>
        {shown.map(({ key, change }) => (
          <ChangeLine key={key} change={change} labels={words} />
        ))}
        {folded.length > 0 ? (
          <TraceCollapsible>
            <TraceCollapsibleTrigger>
              <TraceLine>{words.more(folded.length)}</TraceLine>
            </TraceCollapsibleTrigger>
            <TraceCollapsibleContent>
              <Trace>
                {folded.map(({ key, change }) => (
                  <ChangeLine key={key} change={change} labels={words} />
                ))}
              </Trace>
            </TraceCollapsibleContent>
          </TraceCollapsible>
        ) : null}
      </Trace>
    </Stack>
  );
}

/**
 * One of a brief's three lists about the people a role wants: what they must
 * have, what would be nice, and what rules them out.
 */
export type JobBriefRuleKind = "mustHaves" | "niceToHaves" | "redFlags";

/** A role's sales figures, each as the brief words it ("£400k ARR", say). */
export interface JobBriefRoleDetails {
  /** On-target earnings. Shown as a headline fact, not in the role details. */
  ote?: string | null;
  quota?: string | null;
  equity?: string | null;
  avgDealSize?: string | null;
  biggestDeal?: string | null;
  salesCycle?: string | null;
  motion?: string | null;
}

/** Someone the role sells to. */
export interface JobBriefPersona {
  role?: string | null;
  /** `champion`, `economic_buyer`, `gatekeeper`, `influencer`, or the brief's own word. */
  category?: string | null;
  notes?: string | null;
}

/** One step of the interview process. */
export interface JobBriefInterviewStep {
  /** Where the step falls. Steps without one keep their place in the list. */
  stepNumber?: number | null;
  label?: string | null;
  interviewerName?: string | null;
  expectedFormat?: string | null;
}

/** The hiring company's figures. */
export interface JobBriefCompanyOverview {
  founded?: number | null;
  headcount?: number | null;
  hq?: string | null;
  arr?: readonly { year: number; value: string }[] | null;
  teamDistribution?: readonly { region: string; count: number }[] | null;
}

/**
 * A job brief as display values, under the parsed brief's own field names.
 * Every field is optional; a host maps its own record onto this shape (its
 * stored brief, a job row, a message's snapshot) and `jobBriefView` does the
 * rest, so the same brief reads the same wherever it is shown.
 */
export interface JobBriefContent {
  roleTitle?: string | null;
  companyName?: string | null;
  /** What the role is. Preferred over `summary` as the card's description. */
  roleDescription?: string | null;
  /** A summary of the brief, the description when there is no `roleDescription`. */
  summary?: string | null;
  location?: string | null;
  salaryMin?: number | null;
  salaryMax?: number | null;
  /**
   * The salary's currency, as an ISO 4217 code ("GBP") or a symbol ("£").
   * Without one the salary shows as bare numbers: a currency is never guessed.
   */
  currency?: string | null;
  mustHaves?: readonly string[] | null;
  niceToHaves?: readonly string[] | null;
  redFlags?: readonly string[] | null;
  /** The kinds of company the role targets. */
  icp?: readonly string[] | null;
  roleDetails?: JobBriefRoleDetails | null;
  buyingPersonas?: readonly JobBriefPersona[] | null;
  interviewSteps?: readonly JobBriefInterviewStep[] | null;
  companyOverview?: JobBriefCompanyOverview | null;
  companyWebsite?: string | null;
}

/** One labelled fact, as text. */
export interface JobBriefViewFact {
  id: string;
  label: string;
  value: string;
}

/** A titled part of the brief after its lists, as text. */
export interface JobBriefViewSection {
  id: string;
  title: string;
  facts?: readonly JobBriefViewFact[];
  items?: readonly string[];
  /** Number the items, as for the steps of an interview process. */
  ordered?: boolean;
}

/** The fixed words of a brief, wherever it is shown. */
export interface JobBriefLabels {
  /** The title when the brief names no role, and the `generic` title. */
  title: string;
  /** The must-haves list's name. */
  mustHaves: string;
  /** The nice-to-haves list's name. */
  niceToHaves: string;
  /** The red-flags list's name. */
  redFlags: string;
  /** What one must-have is called, as in "Add must-have…". */
  mustHaveItem: string;
  /** What one nice-to-have is called. */
  niceToHaveItem: string;
  /** What one red flag is called. */
  redFlagItem: string;
  location: string;
  salary: string;
  /** A salary with only a floor, given the formatted amount. */
  salaryFrom: (amount: string) => string;
  /** A salary with only a ceiling, given the formatted amount. */
  salaryUpTo: (amount: string) => string;
  /** On-target earnings. */
  ote: string;
  roleDetails: string;
  quota: string;
  equity: string;
  avgDealSize: string;
  biggestDeal: string;
  salesCycle: string;
  motion: string;
  /** The section listing the kinds of company the role targets. */
  targetCompanyTypes: string;
  buyingPersonas: string;
  /** A persona's category as it reads after the persona's role, by category. */
  personaCategories: Readonly<Record<string, string>>;
  interviewProcess: string;
  /** A step with no label or format, given its number. */
  interviewStep: (number: number) => string;
  /** A step and who runs it. */
  interviewWith: (step: string, interviewer: string) => string;
  company: string;
  website: string;
  founded: string;
  headcount: string;
  hq: string;
  arr: string;
  team: string;
}

/**
 * The lists' names and what one entry of each is called: the part of a
 * brief's wording a JobBriefCard draws itself, which `jobBriefView` hands it
 * as `ruleLabels`.
 */
export type JobBriefRuleLabels = Pick<
  JobBriefLabels,
  "mustHaves" | "niceToHaves" | "redFlags" | "mustHaveItem" | "niceToHaveItem" | "redFlagItem"
>;

/** The default wording of a brief. Pass `labels` to `jobBriefView` to change any of it. */
export const jobBriefLabels: Readonly<JobBriefLabels> = Object.freeze({
  title: "Job brief",
  mustHaves: "Must-haves",
  niceToHaves: "Nice-to-haves",
  redFlags: "Red flags",
  mustHaveItem: "must-have",
  niceToHaveItem: "nice-to-have",
  redFlagItem: "red flag",
  location: "Location",
  salary: "Salary",
  salaryFrom: (amount: string) => `From ${amount}`,
  salaryUpTo: (amount: string) => `Up to ${amount}`,
  ote: "OTE",
  roleDetails: "Role details",
  quota: "Quota",
  equity: "Equity",
  avgDealSize: "Average deal size",
  biggestDeal: "Biggest deal",
  salesCycle: "Sales cycle",
  motion: "Sales motion",
  targetCompanyTypes: "Target company types",
  buyingPersonas: "Buying personas",
  personaCategories: Object.freeze({
    champion: "champion",
    economic_buyer: "economic buyer",
    gatekeeper: "gatekeeper",
    influencer: "influencer",
  }),
  interviewProcess: "Interview process",
  interviewStep: (number: number) => `Step ${number}`,
  interviewWith: (step: string, interviewer: string) => `${step} with ${interviewer}`,
  company: "Company",
  website: "Website",
  founded: "Founded",
  headcount: "Headcount",
  hq: "HQ",
  arr: "ARR",
  team: "Team",
});

/**
 * How `jobBriefView` titles a brief. `role` names it after the role and
 * company ("Account Executive · Example Co"); `generic` is the plain title
 * ("Job brief"), for a page whose own header already names the role.
 */
export type JobBriefTitleStyle = "role" | "generic";

export interface JobBriefViewOptions {
  /**
   * Whether this is the brief in force now (the default) or one a later brief
   * replaced. A current brief previews its first three facts and entries; an
   * earlier one only its title and description, so a history of briefs stays
   * short.
   */
  current?: boolean;
  /** `role` (the default) or `generic`. */
  title?: JobBriefTitleStyle;
  /**
   * `public` for a page anyone holding its link can open: the brief without
   * its red flags, on-target earnings, role details, company figures or
   * interviewers' names. Leave it out where the brief's own team reads it.
   */
  audience?: "public";
  labels?: Partial<JobBriefLabels>;
  /** Further sections after the brief's own, in order, such as the named accounts a role targets. */
  extraSections?: readonly JobBriefViewSection[];
}

/** What a JobBriefCard shows for a brief: spread it onto the card. */
export interface JobBriefView {
  title: string;
  description?: string;
  /** Location, salary and on-target earnings, each only when the brief has it. */
  facts: JobBriefViewFact[];
  mustHaves: string[];
  niceToHaves: string[];
  redFlags: string[];
  /** The lists shown, in order. */
  rules: JobBriefRuleKind[];
  /** Role details, target company types, buying personas, interview process, company, then any extra sections; only those with something in them. */
  sections: JobBriefViewSection[];
  previewCount: number;
  /** The lists' names and what one entry of each is called, from `labels`. */
  ruleLabels: JobBriefRuleLabels;
}

const LOCALE = "en-GB";
const plain = new Intl.NumberFormat(LOCALE, { maximumFractionDigits: 0 });

const ROLE_DETAILS = ["quota", "equity", "avgDealSize", "biggestDeal", "salesCycle", "motion"] as const;

// A title fits a sidebar row and a card heading alike.
const MAX_TITLE_LENGTH = 72;

// Values a parser returns when a field is absent rather than a real value.
const ABSENT_VALUE =
  /^(?:n\/?a|none|null|nil|unknown|tbd|tbc|not (?:specified|provided|stated|known)|unspecified|confidential|undisclosed|untitled|role|job|position|title|various|multiple(?: roles)?|-+)$/i;

/** Trimmed text; absent, blank and non-text are all undefined. */
function text(value: unknown): string | undefined {
  return typeof value === "string" ? value.trim() || undefined : undefined;
}

function finite(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function truncate(value: string, max: number): string {
  const clean = value.trim();
  return clean.length > max ? `${clean.slice(0, max - 3).trimEnd()}…` : clean;
}

/** A title part as display text: whitespace collapsed, quotes and markdown stripped, a placeholder dropped. */
function titleText(value: unknown, max: number): string | undefined {
  if (typeof value !== "string") return undefined;
  const clean = value
    .replace(/\s+/g, " ")
    .replace(/^[\s"'“”‘’`*#]+|[\s"'“”‘’`*]+$/g, "")
    .trim();
  return clean && !ABSENT_VALUE.test(clean) ? truncate(clean, max) : undefined;
}

function capitalise(value: string): string {
  return `${value.charAt(0).toUpperCase()}${value.slice(1)}`;
}

/** Formats one amount: with the currency's symbol when there is one, else a bare grouped number. */
function amountFormat(currency: unknown): (value: number) => string {
  const code = text(currency);
  if (!code) return (value) => plain.format(value);
  try {
    const money = new Intl.NumberFormat(LOCALE, {
      style: "currency",
      currency: code,
      currencyDisplay: "narrowSymbol",
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    });
    return (value) => money.format(value);
  } catch {
    // Not an ISO 4217 code: shown as given, a symbol ("£") against the
    // amount and a word apart from it.
    return (value) => (/\p{L}$/u.test(code) ? `${code} ${plain.format(value)}` : `${code}${plain.format(value)}`);
  }
}

function fact(id: string, label: string, value: string | null | undefined): JobBriefViewFact[] {
  return value ? [{ id, label, value }] : [];
}

/**
 * A brief's title: "Role · Company", or the role alone when there is no
 * company, the role already names it, or the pair would run past 72
 * characters (a long role is cut to fit). A placeholder the parser returns
 * for an absent field ("TBD", "N/A", "Role") counts as no value. With no role,
 * `fallback`.
 */
export function jobBriefTitle(
  content: Pick<JobBriefContent, "roleTitle" | "companyName">,
  fallback: string = jobBriefLabels.title,
): string {
  const role = titleText(content.roleTitle, 240);
  if (!role) return fallback;
  const company = titleText(content.companyName, 120);
  if (company && !role.toLowerCase().includes(company.toLowerCase())) {
    const combined = `${role} · ${company}`;
    if (combined.length <= MAX_TITLE_LENGTH) return combined;
  }
  return truncate(role, MAX_TITLE_LENGTH);
}

/**
 * A brief's salary band in full, grouped numbers: "80,000–100,000", one
 * figure when both ends agree, "From 80,000" or "Up to 100,000" with one
 * end. The currency's symbol leads each amount only when `currency` is set
 * ("£80,000"). Null with neither end.
 */
export function formatJobBriefSalary(
  content: Pick<JobBriefContent, "salaryMin" | "salaryMax" | "currency">,
  labels: Partial<Pick<JobBriefLabels, "salaryFrom" | "salaryUpTo">> = {},
): string | null {
  const min = finite(content.salaryMin);
  const max = finite(content.salaryMax);
  const amount = amountFormat(content.currency);
  if (min !== undefined && max !== undefined) {
    return min === max ? amount(min) : `${amount(Math.min(min, max))}–${amount(Math.max(min, max))}`;
  }
  if (min !== undefined) return (labels.salaryFrom ?? jobBriefLabels.salaryFrom)(amount(min));
  if (max !== undefined) return (labels.salaryUpTo ?? jobBriefLabels.salaryUpTo)(amount(max));
  return null;
}

function persona({ role, category, notes }: JobBriefPersona, categories: Readonly<Record<string, string>>): string {
  const who = text(role);
  const key = text(category);
  const kind = key ? (Object.hasOwn(categories, key) ? categories[key] : key.replace(/_/g, " ")) : undefined;
  const name = who ? (kind ? `${who} (${kind})` : who) : kind ? capitalise(kind) : "";
  return [name, text(notes)].filter(Boolean).join(" — ");
}

function interviewSteps(
  steps: readonly JobBriefInterviewStep[],
  named: boolean,
  labels: JobBriefLabels,
): string[] {
  return steps
    .map((step, index) => ({ step, index }))
    .sort(
      (left, right) =>
        (finite(left.step.stepNumber) ?? left.index + 1) - (finite(right.step.stepNumber) ?? right.index + 1) ||
        left.index - right.index,
    )
    .map(({ step }, index) => {
      const label = text(step.label);
      const format = text(step.expectedFormat);
      const interviewer = text(step.interviewerName);
      const name = label ?? format ?? labels.interviewStep(finite(step.stepNumber) ?? index + 1);
      const run = named && interviewer ? labels.interviewWith(name, interviewer) : name;
      return label && format ? `${run} · ${format}` : run;
    });
}

function companyFacts(content: JobBriefContent, labels: JobBriefLabels): JobBriefViewFact[] {
  const company = content.companyOverview ?? {};
  const founded = finite(company.founded);
  const headcount = finite(company.headcount);
  const arr = [...(company.arr ?? [])]
    .filter(({ year, value }) => finite(year) !== undefined && text(value))
    .sort((left, right) => left.year - right.year)
    .map(({ year, value }) => `${year}: ${text(value)}`);
  const team = (company.teamDistribution ?? [])
    .filter(({ region, count }) => text(region) && finite(count) !== undefined)
    .map(({ region, count }) => `${text(region)} ${plain.format(count)}`);
  return [
    ...fact("website", labels.website, text(content.companyWebsite)),
    ...fact("founded", labels.founded, founded === undefined ? null : String(founded)),
    ...fact("headcount", labels.headcount, headcount === undefined ? null : plain.format(headcount)),
    ...fact("hq", labels.hq, text(company.hq)),
    ...fact("arr", labels.arr, arr.join(" · ")),
    ...fact("team", labels.team, team.join(" · ")),
  ];
}

const ALL_RULES: readonly JobBriefRuleKind[] = ["mustHaves", "niceToHaves", "redFlags"];
const PUBLIC_RULES: readonly JobBriefRuleKind[] = ["mustHaves", "niceToHaves"];

/**
 * What a JobBriefCard shows for a brief, so the same brief reads the same
 * wherever it appears: spread the result onto the card and add only the
 * host's own props (presentation, status, editing, footer, open state).
 *
 * - The title follows `jobBriefTitle`, or is `labels.title` with `title:
 *   "generic"`.
 * - The description is the role description, else the summary, whether the
 *   brief is current or not.
 * - The facts are location, salary (`formatJobBriefSalary`) and on-target
 *   earnings, in that order, each only when the brief has it.
 * - The lists are the brief's own, in its order and as written, so an editable
 *   card hands back exactly what it was given.
 * - The sections are the role details, target company types, buying personas,
 *   the interview process in step order and the company, then
 *   `extraSections`; only those with something in them.
 * - A current brief previews three facts and entries, an earlier one none.
 * - The lists are named, and their entries called, by `labels`, so the
 *   card's controls ("Add must-have…") read the same as the brief.
 *
 * With `audience: "public"`, the red flags, on-target earnings, role details,
 * company section and interviewers' names are left out, and the red-flag list
 * isn't among the `rules`.
 */
export function jobBriefView(content: JobBriefContent, options: JobBriefViewOptions = {}): JobBriefView {
  const { current = true, title = "role", audience, extraSections = [] } = options;
  const labels: JobBriefLabels = {
    ...jobBriefLabels,
    ...options.labels,
    personaCategories: { ...jobBriefLabels.personaCategories, ...options.labels?.personaCategories },
  };
  // A public page leaves out what the role's own team may not want seen outside it.
  const internal = audience !== "public";
  const details = content.roleDetails ?? {};
  const sections: JobBriefViewSection[] = [
    {
      id: "role-details",
      title: labels.roleDetails,
      facts: internal ? ROLE_DETAILS.flatMap((key) => fact(key, labels[key], text(details[key]))) : [],
    },
    { id: "target-company-types", title: labels.targetCompanyTypes, items: [...(content.icp ?? [])] },
    {
      id: "buying-personas",
      title: labels.buyingPersonas,
      items: (content.buyingPersonas ?? []).map((entry) => persona(entry, labels.personaCategories)).filter(Boolean),
    },
    {
      id: "interview-process",
      title: labels.interviewProcess,
      ordered: true,
      items: interviewSteps(content.interviewSteps ?? [], internal, labels),
    },
    { id: "company", title: labels.company, facts: internal ? companyFacts(content, labels) : [] },
    ...extraSections,
  ];

  return {
    title: title === "generic" ? labels.title : jobBriefTitle(content, labels.title),
    description: text(content.roleDescription) ?? text(content.summary),
    facts: [
      ...fact("location", labels.location, text(content.location)),
      ...fact("salary", labels.salary, formatJobBriefSalary(content, labels)),
      ...(internal ? fact("ote", labels.ote, text(details.ote)) : []),
    ],
    mustHaves: [...(content.mustHaves ?? [])],
    niceToHaves: [...(content.niceToHaves ?? [])],
    redFlags: internal ? [...(content.redFlags ?? [])] : [],
    rules: [...(internal ? ALL_RULES : PUBLIC_RULES)],
    sections: sections.filter((section) => (section.facts?.length ?? 0) + (section.items?.length ?? 0) > 0),
    previewCount: current ? 3 : 0,
    ruleLabels: {
      mustHaves: labels.mustHaves,
      niceToHaves: labels.niceToHaves,
      redFlags: labels.redFlags,
      mustHaveItem: labels.mustHaveItem,
      niceToHaveItem: labels.niceToHaveItem,
      redFlagItem: labels.redFlagItem,
    },
  };
}

/* ---------- versions ---------- */

/** The words a brief's version reads in, as `jobBriefVersionLabel` puts them together. */
export interface JobBriefVersionLabels {
  /** A version's number as it reads: "v3". */
  number: (number: number) => string;
  /** What marks the version in force now: "Current". */
  current: string;
  /** What marks a version a later one replaced: "Earlier". Empty for the number alone. */
  earlier: string;
  /** Between the number and its mark: " · ". */
  separator: string;
}

/** The default wording of a brief's version. Pass `labels` to `jobBriefVersionLabel` to change any of it. */
export const jobBriefVersionLabels: Readonly<JobBriefVersionLabels> = Object.freeze({
  number: (number: number) => `v${number}`,
  current: "Current",
  earlier: "Earlier",
  separator: " · ",
});

/**
 * Which version of a brief a card shows: JobBriefCard's `version`, which it
 * draws in its status slot.
 */
export interface JobBriefVersion {
  /** The version's number, counted from 1. */
  number: number;
  /** Whether this is the version in force now, rather than one a later version replaced. */
  current: boolean;
  /** The version's whole wording, in place of `jobBriefVersionLabel`'s. */
  label?: string;
  /**
   * A second, neutral badge after the version's, such as the number another
   * system gives the same version ("Partner v48"), so people using either
   * name the same one.
   */
  secondaryLabel?: string;
}

/**
 * A version's wording: its number and whether it is in force, "v3 · Current"
 * for the version in force now and "v2 · Earlier" for one a later version
 * replaced, so the state is always in words and never in a badge's colour
 * alone. A number that isn't a whole number from 1 is left out, leaving the
 * mark ("Current"); an empty `labels.earlier` leaves an earlier version's
 * number alone ("v2"). The version's own `label`, when it has one, wins.
 */
export function jobBriefVersionLabel(
  version: Pick<JobBriefVersion, "number" | "current" | "label">,
  labels: Partial<JobBriefVersionLabels> = {},
): string {
  const own = text(version.label);
  if (own) return own;
  const words = { ...jobBriefVersionLabels, ...labels };
  const number = validVersion(version.number) ? words.number(version.number) : "";
  const mark = version.current ? words.current : words.earlier;
  return [number, mark].filter(Boolean).join(words.separator);
}

function validVersion(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value > 0;
}

/* ---------- what a version changed ---------- */

/**
 * What one change did: `set` a field's value, `cleared` it, `added` or
 * `removed` a list's entry, `reworded` one, `moved` one, or `replaced` a
 * whole field (a list of steps, say) at once.
 */
export type JobBriefChangeKind = "set" | "cleared" | "added" | "removed" | "reworded" | "moved" | "replaced";

/**
 * A value as a change shows it: text (whitespace collapsed, cut to 80
 * characters), a number (grouped, "80,000", so pass a year as text), or a
 * list, counted ("3 entries").
 */
export type JobBriefChangeValue = string | number | readonly unknown[];

/**
 * One change a version of a brief made, as display values: a host maps its
 * own record of a change onto this, naming the field in its own words.
 *
 * | kind | reads | uses |
 * | --- | --- | --- |
 * | `added` | Added must-have: Python | `item` |
 * | `removed` | Removed red flag: Job hopping | `item` |
 * | `reworded` | Reworded must-have: "Python" → "Python 3" | `from`, `to` |
 * | `moved` | Moved must-have "Python" to position 1 | `item`, `to` (the position) |
 * | `set` | Location: Remote → Hybrid | `fieldTitle`, `from`, `to` |
 * | `cleared` | Removed the location (was Remote) | `from` |
 * | `replaced` | Replaced the interview steps (3 entries) | `to` |
 *
 * With `prose`, the line says only that the field was added, updated or
 * removed ("Updated the role description"), since its text would swamp a line.
 */
export interface JobBriefChange {
  /** Stable key for the line. Defaults to its place in the list. */
  id?: string;
  kind: JobBriefChangeKind;
  /** The field's name as it reads mid-sentence: "must-have", "location", "OTE". */
  field: string;
  /** The field's name where it leads a `set` line: "Location". Defaults to `field` with a capital. */
  fieldTitle?: string;
  /** The list entry an `added`, `removed` or `moved` change is about. */
  item?: string | null;
  /**
   * What it was: a `reworded` entry's old words, a `set` field's old value,
   * a `cleared` field's last value. Left out for a field set for the first time.
   */
  from?: JobBriefChangeValue | null;
  /**
   * What it is now: a `reworded` entry's new words, a `set` field's new
   * value, what a `replaced` field holds now. For `moved`, the entry's new
   * position, counted from 1.
   */
  to?: JobBriefChangeValue | null;
  /**
   * A prose field, such as a role description or a summary: the line says
   * only that it was added (no `from`), updated (a `from`) or removed
   * (`cleared`), never its text.
   */
  prose?: boolean;
}

/**
 * The words a version's changes read in. Each line's wording takes its
 * values already shaped for a line, and an empty string for one that is
 * absent.
 */
export interface JobBriefChangeLabels {
  /** "Added must-have: Python". */
  added: (field: string, item: string) => string;
  /** "Removed red flag: Job hopping". */
  removed: (field: string, item: string) => string;
  /** 'Reworded must-have: "Python" → "Python 3"'. */
  reworded: (field: string, from: string, to: string) => string;
  /** 'Moved must-have "Python" to position 1'; without a position, 'Moved must-have "Python"'. */
  moved: (field: string, item: string, position: string) => string;
  /** "Location: Remote → Hybrid"; without an old value, "Location: Hybrid". */
  set: (fieldTitle: string, from: string, to: string) => string;
  /** "Removed the location (was Remote)"; without its last value, "Removed the location". */
  cleared: (field: string, from: string) => string;
  /** "Replaced the interview steps (3 entries)". */
  replaced: (field: string, to: string) => string;
  /** A prose field set for the first time: "Added a role description". */
  proseAdded: (field: string) => string;
  /** A prose field rewritten: "Updated the role description". */
  proseUpdated: (field: string) => string;
  /** A prose field removed: "Removed the role description". */
  proseCleared: (field: string) => string;
  /** A list as a value, by how many entries it holds: "3 entries". */
  entries: (count: number) => string;
  /** JobBriefChanges' toggle, by how many changes it folds away: "2 more changes". */
  more: (count: number) => string;
  /** JobBriefChanges' name for a screen reader, by the version the changes made: "What changed in v3". */
  groupName: (version?: number) => string;
}

/** The default wording of a version's changes. Pass `labels` to change any of it. */
export const jobBriefChangeLabels: Readonly<JobBriefChangeLabels> = Object.freeze({
  added: (field: string, item: string) => (item ? `Added ${field}: ${item}` : `Added ${field}`),
  removed: (field: string, item: string) => (item ? `Removed ${field}: ${item}` : `Removed ${field}`),
  reworded: (field: string, from: string, to: string) =>
    from && to ? `Reworded ${field}: "${from}" → "${to}"` : to ? `Reworded ${field}: "${to}"` : `Reworded ${field}`,
  moved: (field: string, item: string, position: string) => {
    const moved = item ? `Moved ${field} "${item}"` : `Moved ${field}`;
    return position ? `${moved} to position ${position}` : moved;
  },
  set: (fieldTitle: string, from: string, to: string) =>
    from && to ? `${fieldTitle}: ${from} → ${to}` : to ? `${fieldTitle}: ${to}` : fieldTitle,
  cleared: (field: string, from: string) => (from ? `Removed the ${field} (was ${from})` : `Removed the ${field}`),
  replaced: (field: string, to: string) => (to ? `Replaced the ${field} (${to})` : `Replaced the ${field}`),
  proseAdded: (field: string) => `Added ${/^[aeiou]/i.test(field) ? "an" : "a"} ${field}`,
  proseUpdated: (field: string) => `Updated the ${field}`,
  proseCleared: (field: string) => `Removed the ${field}`,
  entries: (count: number) => `${plain.format(count)} ${count === 1 ? "entry" : "entries"}`,
  more: (count: number) => `${plain.format(count)} more ${count === 1 ? "change" : "changes"}`,
  groupName: (version?: number) =>
    validVersion(version) ? `What changed in ${jobBriefVersionLabels.number(version)}` : "What changed",
});

// A value longer than this is cut, so one change never swamps its line.
const MAX_CHANGE_VALUE_LENGTH = 80;
const grouped = new Intl.NumberFormat(LOCALE);

/** A change's value as a line shows it, or an empty string for none. */
function changeValue(value: unknown, labels: JobBriefChangeLabels): string {
  if (typeof value === "string") {
    // Cut by characters, never through one (a surrogate pair stays whole).
    const characters = Array.from(value.replace(/\s+/g, " ").trim());
    return characters.length > MAX_CHANGE_VALUE_LENGTH
      ? `${characters.slice(0, MAX_CHANGE_VALUE_LENGTH - 3).join("").trimEnd()}…`
      : characters.join("");
  }
  if (typeof value === "number") return Number.isFinite(value) ? grouped.format(value) : "";
  if (Array.isArray(value)) return labels.entries(value.length);
  return "";
}

/**
 * One change as a line: "Added must-have: Python", "Location: Remote →
 * Hybrid", "Removed the location (was Remote)", in the field's own words
 * (`field`, and `fieldTitle` where it leads the line). Each value is shaped
 * for a line: text with its whitespace collapsed and cut to 80 characters
 * with an ellipsis, a number grouped ("80,000"), a list counted ("3
 * entries"). A `set` with nothing new and an old value reads as `cleared`; a
 * `prose` field says only that it was added, updated or removed.
 */
export function jobBriefChangeText(change: JobBriefChange, labels: Partial<JobBriefChangeLabels> = {}): string {
  const words: JobBriefChangeLabels = { ...jobBriefChangeLabels, ...labels };
  const field = text(change.field) ?? "";
  const from = changeValue(change.from, words);
  const to = changeValue(change.to, words);
  const item = changeValue(change.item, words);
  if (change.prose) {
    if (change.kind === "cleared" || change.kind === "removed") return words.proseCleared(field);
    return from ? words.proseUpdated(field) : words.proseAdded(field);
  }
  switch (change.kind) {
    case "added":
      return words.added(field, item);
    case "removed":
      return words.removed(field, item);
    case "reworded":
      return words.reworded(field, from, to);
    case "moved":
      return words.moved(field, item, to);
    case "cleared":
      return words.cleared(field, from);
    case "replaced":
      return words.replaced(field, to);
    case "set":
    default:
      // A kind this release doesn't know reads as a new value, never as nothing.
      if (!to && from) return words.cleared(field, from);
      return words.set(text(change.fieldTitle) ?? capitalise(field), from, to);
  }
}

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
