  /** The host's check of the call against its open roles. */
  insights: CallInsights;
  /** The roles the check suggested. Once insights are ready and this is empty, the card says no role fits. */
  roleMatches?: ReactNode;
  labels?: Partial<MatchedCallCardLabels>;
  /** Class for the card. Its root is the kit's CallCard, which takes no other attributes. */
  className?: string;
}

const isShown = (node: ReactNode) => node != null && node !== false && node !== "";

const noSearch: SearchCallPeople<never> = async () => [];

/**
 * A call already linked to one or more people, so it can be found again: the
 * linked people head the card and open each person, the transcript loads in
 * full when opened, and the footer holds the call's insights with a generate
 * action. A header action links the call to one more person through a search
 * dialog. The card keeps no record of its own: the host updates `people`
 * once a link is saved.
 */
export function MatchedCallCard<TPerson extends CallPerson>({
  title,
  people = [],
  onOpenPerson,
  source,
  timestamp,
  participants,
  summary,
  transcript,
  segments,
  loadTranscript,
  linkPerson,
  insights,
  roleMatches,
  labels,
  className,
}: MatchedCallCardProps<TPerson>) {
  const text = { ...DEFAULT_LABELS, ...labels };
  const call = useCallTranscript({ transcript, segments, loadTranscript });
  const [linkOpen, setLinkOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [linking, setLinking] = useState(false);
  const { results, searching } = useCallPeopleSearch<TPerson>(
    query,
    linkOpen && linkPerson != null,
    linkPerson?.searchPeople ?? noSearch,
  );
  const ready = insights.status === "ready";

  async function link(person: TPerson) {
    if (!linkPerson) return;
    setLinking(true);
    try {
      await linkPerson.onLink(person);
      setLinkOpen(false);
      setQuery("");
    } catch {
      // The host has said why; the dialog stays open to try again.
    } finally {
      setLinking(false);
    }
  }

  const heading = people.length > 0 ? (
    <Stack direction="horizontal" gap="xs" align="center" wrap>
      {people.map((person, index) => (
        <Fragment key={person.id}>
          {index > 0 && <Text as="span" variant="inherit">{text.peopleSeparator}</Text>}
          {onOpenPerson ? (
            <Button
              variant="ghost"
              size="compact"
              onClick={() => onOpenPerson(person)}
              aria-label={text.openPerson(person.name)}
            >
              {person.name}
            </Button>
          ) : (
            <Text as="span" variant="inherit">{person.name}</Text>
          )}
        </Fragment>
      ))}
    </Stack>
  ) : (title || text.untitled);

  return (
    <>
      <CallCard
        className={className}
        title={heading}
        source={source}
        timestamp={timestamp}
        participants={participants as CallParticipant[] | undefined}
        summary={summary}
        headerAside={linkPerson ? (
          <Button variant="outline" size="compact" onClick={() => setLinkOpen(true)} disabled={linking}>
            {text.linkPerson}
          </Button>
        ) : undefined}
        transcript={call.transcript}
        segments={call.segments}
        transcriptLabel={text.showTranscript}
        onLoadTranscript={call.onLoadTranscript}
        actions={
          <Stack gap="md" width="full" textAlign="start">
            <Stack direction="horizontal" justify="between" align="center">
              <Stack direction="horizontal" gap="xs" align="center">
                <Icon icon={Sparkles} size="sm" />
                <Text variant="small" weight="medium">{text.insights}</Text>
              </Stack>
              <Button variant="ghost" size="compact" onClick={() => insights.onGenerate(ready)} disabled={insights.generating}>
                {insights.generating ? <Icon icon={Loader2} size="sm" spin /> : <Icon icon={Sparkles} size="sm" />} {ready ? text.regenerate : text.generate}
              </Button>
            </Stack>
            {/* Keep generated insights directly beneath their action. */}
            {ready && (
              isShown(roleMatches) ? roleMatches : (
                <EmptyState
                  variant="empty"
                  size="inline"
                  icon={BriefcaseBusiness}
                  title={text.noRolesTitle}
                  description={text.noRolesDescription}
                />
              )
            )}
            {insights.error && <Text variant="small" tone="destructive">{insights.error}</Text>}
          </Stack>
        }
      />
      {linkPerson && (
        <ResponsiveDialog open={linkOpen} onOpenChange={setLinkOpen}>
          <ResponsiveDialogContent>
            <ResponsiveDialogHeader><ResponsiveDialogTitle>{text.linkTitle}</ResponsiveDialogTitle></ResponsiveDialogHeader>
            <ResponsiveDialogBody>
              <Stack gap="sm">
                <Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={text.searchPlaceholder} autoFocus />
                {searching && <Text variant="small" tone="muted">{text.searching}</Text>}
                {results.length > 0 && (
                  <List surface="bordered" radius="md">
                    {results.map((person) => (
                      <ListItem key={person.id}>
                        <Button variant="ghost" width="full" align="start" onClick={() => void link(person)} disabled={linking}>
                          {person.name}
                        </Button>
                      </ListItem>
                    ))}
                  </List>
                )}
                {!searching && query.trim().length >= CALL_PEOPLE_SEARCH_MIN_LENGTH && results.length === 0 && (
                  <EmptyState
                    variant="search"
                    size="inline"
                    icon={UserSearch}
                    title={text.noMatchesTitle}
                    description={text.noMatchesDescription}
                  />
                )}
              </Stack>
            </ResponsiveDialogBody>
          </ResponsiveDialogContent>
        </ResponsiveDialog>
      )}
    </>
  );
}

import { useRef, useState } from "react";

function isPromiseLike(value: unknown): value is PromiseLike<unknown> {
  return value != null && typeof (value as PromiseLike<unknown>).then === "function";
}

/**
 * Runs a host callback with the arguments given. While a returned promise is
 * pending, `pending` is true and `pendingArgs` holds what the latest call
 * passed, so a control can keep showing what it sent (a list it saved, say)
 * until the host answers, without the host tracking it. Only the latest call
 * settles the state: an earlier promise that settles after a later call began
 * changes nothing. A callback that returns no promise is never pending. The
 * host handles a failure in its own callback; this only waits for it to
 * settle.
 */
export function usePendingCall<TArgs extends unknown[]>(
  action: ((...args: TArgs) => unknown) | undefined,
) {
  const [pendingArgs, setPendingArgs] = useState<TArgs | null>(null);
  const latest = useRef(0);
  const run = (...args: TArgs) => {
    if (!action) return;
    const call = ++latest.current;
    const result = action(...args);
    if (isPromiseLike(result)) {
      setPendingArgs(args);
      const settle = () => {
        if (latest.current === call) setPendingArgs(null);
      };
      void Promise.resolve(result).then(settle, settle);
    } else {
      setPendingArgs(null);
    }
  };
  return [pendingArgs !== null, run, pendingArgs] as const;
}

/**
 * Runs a button's action. While a returned promise is pending, `pending` is
 * true, so the button can show a spinner or disable itself without the host
 * tracking which row is busy. The host handles a failure in its own callback;
 * the button only waits for it to settle. The runner passes none of its own
 * arguments on, so it can be a click handler without handing the host the
 * event.
 */
export function usePendingAction(action: (() => unknown) | undefined) {
  const [pending, run] = usePendingCall(action);
  return [pending, () => run()] as const;
}

// A compact control is sized for a mouse. On a coarse pointer (a touchscreen)
// it grows to a 44px touch target, whatever size it asked for; a mouse keeps
// the dense size. 44 CSS pixels rather than the kit's h-11 (2.75rem): below
// 768px the kit scales its root type to 87.5%, which makes h-11 38.5px on a
// phone, and the larger of the two where a host's root is bigger. min-height
// and min-width rather than a size, so a control already larger keeps its own.

/** On a coarse pointer, this element is at least 44px square. */
export const COARSE_POINTER_TOUCH_TARGET =
  "pointer-coarse:min-h-[max(44px,2.75rem)] pointer-coarse:min-w-[max(44px,2.75rem)]";

/** On a coarse pointer, every link and button inside this element is at least 44px square. */
export const COARSE_POINTER_TOUCH_TARGETS_WITHIN =
  "pointer-coarse:[&_a]:min-h-[max(44px,2.75rem)] pointer-coarse:[&_a]:min-w-[max(44px,2.75rem)] pointer-coarse:[&_button]:min-h-[max(44px,2.75rem)] pointer-coarse:[&_button]:min-w-[max(44px,2.75rem)]";
